import {
  getStorageDataLocal,
  setStorageDataLocal,
} from "../../../chrome/chrome.utils";

// SUB-09 — rollback-proof trial clock (in-session high-water-mark).
//
// Trial expiry is decided by comparing a stored end-instant against the wall
// clock (`Date.now()`). A free user whose trial has already lapsed can roll
// their system clock BACK to before the trial end and the naive comparison
// re-grants PRO indefinitely. We defend with a monotonic high-water mark: the
// largest wall-clock instant we have ever observed, persisted to local storage.
// Every trial check reads `monotonicNow()` = max(Date.now(), highWaterMark), so
// once real time has passed the trial end the mark stays past it and a backward
// clock jump can no longer resurrect the trial. The mark only ever moves
// FORWARD, so a legitimately advancing clock is unaffected.
//
// This is intentionally NOT a security boundary (a determined user can clear
// extension storage); it closes the trivial "set the date back" bypass, which
// is the realistic abuse path. Paid entitlement is backend-authoritative and
// does not rely on this.

export const MONOTONIC_CLOCK_HWM_KEY = "highlighty.monotonicClockHwmMs";

// Persist at most this often (ms) — `monotonicNow` is called on every
// entitlement render, but the mark only needs to survive a reload, so a coarse
// write cadence keeps storage churn negligible while never losing more than this
// window of advancement.
const PERSIST_THROTTLE_MS = 30_000;

// SUB-24: the mark is the latest wall-clock instant ever OBSERVED, so it may
// legitimately sit AHEAD of a rolled-back clock — that ahead-ness is exactly the
// SUB-09 rollback deterrent, so we must NOT reject every future-dated mark. But
// a value FAR in the future (e.g. a clock once mis-set to a future year, or a
// runaway RTC) gets locked in by the forward-only invariant and never recovers:
// `monotonicNow()` keeps returning that future instant even after the clock is
// corrected, permanently expiring a live trial and downgrading a canceled-but-
// in-period PAID subscriber. A mark more than this many ms ahead of the current
// clock cannot come from a realistic in-trial-window rollback (trials are at most
// weeks), so we treat it as corrupt and re-anchor to the current clock. Realistic
// sub-window forward excursions (DST, NTP, VM drift) are kept and self-heal as
// real time advances. (Clearing storage still defeats the deterrent entirely —
// SUB-09 was never a hard boundary.)
const MAX_CLOCK_AHEAD_MS = 90 * 24 * 60 * 60 * 1000; // 90 days

let highWaterMarkMs = 0;
let lastPersistedMs = 0;
// SUB-26: have we loaded the persisted mark yet? `monotonicNow` must not WRITE
// before the stored value has been read — an unseeded context (a background SW
// that never seeded, or a call racing onStart's seed) would otherwise blind-
// write its raw-Date.now() fallback and could LOWER a higher stored mark,
// weakening the cross-context rollback defense. It still RETURNS the correct
// max; it just doesn't persist until seeding has run.
let seeded = false;

// Pure core, unit-tested in isolation: the mark can only move forward.
export const clampToHighWaterMark = (nowMs: number, hwmMs: number): number =>
  nowMs > hwmMs ? nowMs : hwmMs;

const persistHighWaterMark = (valueMs: number): void => {
  // Best-effort, fire-and-forget. Storage may be unavailable (jsdom/tests) — the
  // helper returns undefined there and we simply skip. A rejected write must
  // never bubble into an entitlement check.
  try {
    const result = setStorageDataLocal<number>({
      [MONOTONIC_CLOCK_HWM_KEY]: valueMs,
    });
    if (result && typeof (result as Promise<void>).catch === "function") {
      (result as Promise<void>).catch(() => undefined);
    }
    lastPersistedMs = valueMs;
  } catch {
    // ignore — the in-memory mark still protects this session
  }
};

// Monotonically non-decreasing "now". Returns max(Date.now(), high-water mark)
// and advances the mark. Safe to call synchronously from any entitlement gate.
export const monotonicNow = (): number => {
  const wallNow = Date.now();
  highWaterMarkMs = clampToHighWaterMark(wallNow, highWaterMarkMs);
  // SUB-26: only persist once the stored mark has been loaded (seeded), so an
  // unseeded context can't lower a higher stored value (see `seeded` above).
  if (seeded && highWaterMarkMs - lastPersistedMs >= PERSIST_THROTTLE_MS) {
    persistHighWaterMark(highWaterMarkMs);
  }
  return highWaterMarkMs;
};

// Load the persisted mark into memory at startup so the high-water value
// survives reloads (and therefore a clock rollback across a reload). Idempotent;
// callers should `await` this once during init before the first entitlement
// check, but `monotonicNow` is still safe (in-session-only) if it hasn't run.
export const seedMonotonicClock = async (): Promise<number> => {
  let persisted = 0;
  try {
    const result = getStorageDataLocal<Record<string, number>>(
      MONOTONIC_CLOCK_HWM_KEY
    );
    if (result) {
      const data = await result;
      const stored = data?.[MONOTONIC_CLOCK_HWM_KEY];
      // SUB-24: accept a finite stored mark ONLY if it isn't implausibly far in
      // the future. A mark up to MAX_CLOCK_AHEAD_MS ahead of the current clock is
      // kept (it may be a legitimate high-water value ahead of a rolled-back
      // clock — the SUB-09 deterrent); a value beyond that is a corrupt /
      // forward-mis-set clock that the forward-only invariant would otherwise
      // lock in forever, so it is dropped and the clock re-anchors to `now`.
      if (
        typeof stored === "number" &&
        Number.isFinite(stored) &&
        stored <= Date.now() + MAX_CLOCK_AHEAD_MS
      ) {
        persisted = stored;
      }
    }
  } catch {
    // ignore — fall back to the in-memory / wall value
  }
  highWaterMarkMs = clampToHighWaterMark(
    clampToHighWaterMark(Date.now(), highWaterMarkMs),
    persisted
  );
  // Re-anchor the persisted copy if memory now leads it (e.g. real time advanced
  // past the stored mark since the last write), so a subsequent rollback is
  // caught even before the throttle window elapses.
  if (highWaterMarkMs > persisted) {
    persistHighWaterMark(highWaterMarkMs);
  } else {
    lastPersistedMs = persisted;
  }
  // SUB-26: the stored mark is now loaded — `monotonicNow` may persist from here.
  seeded = true;
  return highWaterMarkMs;
};

// Test-only: reset module state between cases.
export const __resetMonotonicClockForTests = (): void => {
  highWaterMarkMs = 0;
  lastPersistedMs = 0;
  seeded = false;
};
