import { QuerySearchOptions } from "./types";

const COMBINING_MARKS_REGEX = /[\u0300-\u036f]/g;
const WHITESPACE_REGEX = /\s/;

// HLE-15 (Cmd+F harmonization): fold every typographic apostrophe/quote to its
// straight-ASCII form so the Cmd+F engine matches the smart-quote prose the web
// publishes, mirroring the equivalence the on-page mark.js highlighter emits
// (createRegExp). Applied to BOTH the term and the document text (they run
// through the same normalizer), so it stays symmetric. Each mapped char is a
// single code point \u2192 a single ASCII code point, so the 1-source-index-per-
// output-code-unit invariant normalizeSearchTextWithMap relies on is preserved.
//   \u2018 \u2019 \u201a \u02bc (U+2018/2019/201A/02BC) \u2192 '   |   \u201c \u201d \u201e (U+201C/201D/201E) \u2192 "
const TYPOGRAPHIC_APOSTROPHES_REGEX = /[\u2018\u2019\u201a\u02bc]/g;
const TYPOGRAPHIC_QUOTES_REGEX = /[\u201c\u201d\u201e]/g;

// QRX-21: fold non-decomposing stroke/ligature letters to their ASCII base so
// the Cmd+F / form-field / PDF search engine is diacritic-insensitive for them
// too, matching the on-page mark.js highlighter (HLE-21). The NFD + strip-
// combining pass below handles letters that decompose to base+mark (\u00e9\u2192e, \u00f1\u2192n),
// but stroke/hook/bar letters like \u00f8/\u0111/\u0142/\u0127/\u0253/\u0199 have NO combining-mark
// decomposition \u2014 NFD leaves them unchanged \u2014 so they need an explicit base map.
// Applied to BOTH the term and the document text (they run through the SAME
// normalizer), so the fold stays symmetric. Each entry maps ONE code point \u2192 ONE
// code point, preserving normalizeSearchTextWithMap's 1-source-index-per-output-
// code-unit invariant (unlike a two-char expansion).
//
// This is EXACTLY the set of non-decomposing letters the highlighter's HLE-21
// reverse index folds (the values inside mark.js `createDiacriticsRegExp`'s
// `diacriticMap` classes that NFD leaves intact), so the two surfaces agree.
// Kept in sync via a one-off extraction from that map. Two-char / transliteration
// cases (\u00df\u2192ss, \u00fe\u2192th, \u0133\u2192ij) and the locale letter \u0131 are deliberately OUT \u2014 a
// per-char replacement can't express them and they need a product decision.
// HLE-23 closed the `\u01ae` (U+01AE) case-fold gap (added below next to \u01ac\u2192T);
// \u01ff/\u01fe fold via the NFD+strip pass (\u01ff\u2192\u00f8\u2192o), so they need no explicit entry.
const STROKE_LETTER_FOLD: Record<string, string> = {
  \u0180: "b", \u0183: "b", \u0253: "b", \u0243: "B", \u0182: "B", \u0181: "B",
  \u0188: "c", \u023c: "c", \u0187: "C", \u023b: "C",
  \u0111: "d", \u018c: "d", \u0256: "d", \u0257: "d", \u0110: "D", \u018b: "D", \u0189: "D", \u018a: "D",
  \u0192: "f", \u0191: "F",
  \u01e5: "g", \u01a3: "g", \u01e4: "G", \u01a2: "G",
  \u0127: "h", \u0126: "H",
  \u0199: "k", \u0198: "K",
  \u019a: "l", \u0142: "l", \u023d: "L", \u0141: "L",
  \u00f8: "o", \u00d8: "O",
  \u01a5: "p", \u01a4: "P",
  \u01ad: "t", \u0288: "t", \u01ac: "T", \u01ae: "T",
};
// Built from the map keys so it can never drift from STROKE_LETTER_FOLD. All
// keys are single BMP letters (no regex-special chars), safe inside a class.
const STROKE_LETTER_REGEX = new RegExp(
  "[" + Object.keys(STROKE_LETTER_FOLD).join("") + "]",
  "g"
);

export function normalizeSearchText(
  value: string,
  options: Pick<QuerySearchOptions, "caseSensitive" | "diacriticSensitive">
) {
  let normalizedValue = value;

  if (!options.diacriticSensitive) {
    normalizedValue = normalizedValue
      .normalize("NFD")
      .replace(COMBINING_MARKS_REGEX, "")
      // QRX-21: fold non-decomposing stroke/ligature letters (ø đ ł ħ + case)
      // that NFD leaves intact, so they match their plain base like the on-page
      // highlighter does. 1:1, so the sourceMap invariant is untouched.
      .replace(STROKE_LETTER_REGEX, (ch) => STROKE_LETTER_FOLD[ch]);
  }

  // Quote-family folding is 1:1 and independent of the diacritic/case toggles \u2014
  // a straight and a curly apostrophe are the "same" character for search.
  normalizedValue = normalizedValue
    .replace(TYPOGRAPHIC_APOSTROPHES_REGEX, "'")
    .replace(TYPOGRAPHIC_QUOTES_REGEX, '"');

  if (!options.caseSensitive) {
    normalizedValue = normalizedValue.toLowerCase();
  }

  return normalizedValue;
}

export function normalizeSearchTextWithMap(
  value: string,
  options: Pick<QuerySearchOptions, "caseSensitive" | "diacriticSensitive">
) {
  let normalizedValue = "";
  const sourceMap: number[] = [];
  let lastWasWhitespace = false;

  // QRX-09: iterate by CODEPOINT, not UTF-16 code unit. A `for…of` over a
  // string yields whole codepoints, so a cased astral char (Deseret 𐐀, Adlam,
  // Osage…) is handed to normalizeSearchText() intact and lowercases the same
  // way the query path does (which folds the whole string at once). The old
  // `value[index]` handed toLowerCase() a lone surrogate, which it can't fold,
  // desyncing the document side from the query side for those scripts. `index`
  // is advanced by the codepoint's code-unit length so sourceMap entries keep
  // pointing at the right UTF-16 offset in `value`.
  let index = 0;
  for (const rawChar of value) {
    const charLength = rawChar.length;
    if (WHITESPACE_REGEX.test(rawChar)) {
      if (!lastWasWhitespace) {
        normalizedValue += " ";
        sourceMap.push(index);
        lastWasWhitespace = true;
      }
      index += charLength;
      continue;
    }

    const nextValue = normalizeSearchText(rawChar, options);

    // QRX-08: only clear the whitespace flag once we actually EMIT a
    // non-whitespace char. A char that folds to "" (a combining mark stripped
    // under diacritic-insensitive search) must NOT reset the flag — otherwise a
    // following whitespace run sees lastWasWhitespace=false and emits a SECOND
    // space, so "a␠´␠b" collapses to "a  b" (two spaces) and a phrase search
    // for "a b" misses.
    if (!nextValue.length) {
      index += charLength;
      continue;
    }

    lastWasWhitespace = false;

    // Push ONE sourceMap entry per output UTF-16 CODE UNIT (not per codepoint):
    // normalizedToTextMap is indexed downstream by UTF-16 offsets from
    // String.indexOf, so the invariant sourceMap.length === value.length must
    // hold even when a folded char is astral (e.g. 𐐀→𐐨, two code units).
    normalizedValue += nextValue;
    for (let unit = 0; unit < nextValue.length; unit += 1) {
      sourceMap.push(index);
    }
    index += charLength;
  }

  const leadingWhitespace = normalizedValue.match(/^ +/)?.[0].length ?? 0;
  const trailingWhitespace = normalizedValue.match(/ +$/)?.[0].length ?? 0;

  return {
    value: normalizedValue.trim(),
    sourceMap:
      trailingWhitespace > 0
        ? sourceMap.slice(
            leadingWhitespace,
            sourceMap.length - trailingWhitespace
          )
        : sourceMap.slice(leadingWhitespace),
  };
}

// The word-character class shared by every whole-word surface: a boundary
// exists wherever the adjacent char is NOT one of these. \p{M} (combining marks)
// count as word-CONTINUATION so an NFD accent doesn't read as a boundary (QRX-11).
export const WORD_CHAR_CLASS = "[\\p{L}\\p{N}\\p{M}_]";

// Compiled once (no `g` flag → no lastIndex state) and reused — isWordBoundary
// is a hot per-character filter, so a fresh RegExp per call would regress it.
const WORD_CHAR_RE = new RegExp(WORD_CHAR_CLASS, "u");

export function isWordBoundary(value: string, index: number) {
  if (index < 0 || index >= value.length) return true;

  // QRX-17: read the whole CODE POINT at `index`, not a lone UTF-16 code unit.
  // `value[index]` is one code unit; for an astral word char (Deseret `𐐀`, the
  // mathematical digits `𝟙`, astral CJK Ext-B, …) that unit is a lone surrogate,
  // which WORD_CHAR_RE (compiled `u`) rejects → the old code reported a boundary
  // there, so plain-path whole-word OVER-matched a sub-word abutting an astral
  // letter/digit while the `wrapRegexWholeWord` lookaround (which sees the full
  // code point) did not — a plain-vs-regex divergence. If `index` lands on a LOW
  // surrogate (the tail of a pair, e.g. the char just before a match that begins
  // right after an astral grapheme), step back to its high surrogate so
  // `codePointAt` yields the whole astral code point. (Same code-unit-vs-code-
  // point root as QRX-09.)
  let cpIndex = index;
  const unit = value.charCodeAt(cpIndex);
  if (unit >= 0xdc00 && unit <= 0xdfff && cpIndex > 0) {
    cpIndex -= 1;
  }
  const codePoint = value.codePointAt(cpIndex);
  if (codePoint === undefined) return true;

  // QRX-11: treat a combining mark (\p{M}) as word-CONTINUATION, not a boundary.
  // The regex whole-word filter (queryMatching.ts) runs this over RAW text; an
  // NFD letter+accent like "café" keeps U+0301 after "cafe", and without \p{M}
  // here that trailing mark read as a word boundary, so a regex `cafe` was kept
  // as a whole word. The plain path filters in normalized (mark-stripped) space,
  // so this aligns the regex path with it. Marks never appear adjacent to a real
  // letter boundary in normalized text, so the plain path is unaffected.
  return !WORD_CHAR_RE.test(String.fromCodePoint(codePoint));
}

// QRX-06: apply whole-word semantics to a regex by wrapping the user's pattern
// in ZERO-WIDTH Unicode word-boundary lookarounds. Used by the on-page mark.js
// highlighter (content.highlight.ts), which — unlike the Cmd+F/PDF engines
// (QRX-03) — has no single match-offset string to post-filter with
// isWordBoundary, so it must constrain the pattern itself.
//
// Mirrors isWordBoundary's word-char class exactly, so the three regex surfaces
// agree. Lookarounds are zero-width → the highlight still covers ONLY the user's
// match (no swallowed boundary chars). The user pattern is wrapped in a
// NON-capturing group so top-level alternation (`cat|dog`) is scoped correctly
// and capture-group numbering / backreferences are preserved (no new capturing
// group is introduced, so mark.js's `ignoreGroups: 0` stays valid). At a string
// edge the lookarounds are vacuously satisfied — matching isWordBoundary's
// out-of-range `true`. The pattern MUST be compiled with the `u` flag (the
// caller already uses `gmu…`) for the \p{…} classes to be valid.
export function wrapRegexWholeWord(source: string): string {
  return `(?<!${WORD_CHAR_CLASS})(?:${source})(?!${WORD_CHAR_CLASS})`;
}

// QRX-20: compile a user regex, optionally whole-word-wrapped, validating the
// RAW pattern FIRST. Without the raw check, an unterminated character class like
// `cat[` — a compile error on its own, so correctly rejected — becomes a VALID
// but semantically unrelated regex once `wrapRegexWholeWord` appends `(?!CLASS)`,
// whose `]` closes the user's dangling `[` and swallows the lookahead as class
// contents. The SAME query would then behave differently with whole-word ON
// (matches garbage) vs OFF (no matches). Validating the raw source first makes a
// malformed pattern fail identically regardless of the toggle. Throws (like
// `new RegExp`) on an invalid pattern; callers keep their existing try/catch and
// run the catastrophic guard on the raw source BEFORE calling this.
export function compileWholeWordRegex(
  source: string,
  flags: string,
  wholeWord: boolean
): RegExp {
  // Reject a malformed RAW pattern up front — the wrap must not be able to
  // "rescue" a broken character class into a valid-but-wrong regex.
  // eslint-disable-next-line no-new
  new RegExp(source, flags);
  return new RegExp(wholeWord ? wrapRegexWholeWord(source) : source, flags);
}
