// On-install trial bootstrap. Mirrors what the popup's
// useInitAccountSubscription hook does on first load: resolve a
// guest-trial subscription and write it to chrome.storage.local so the
// content script's freemium converter sees an active trial and stops
// clamping PRO modifiers (regex, fuzzy, snippets, etc.) in the Cmd+F bar.
//
// Without this, a fresh install gets a working Cmd+F intercept but only
// the free-tier modifier chips until the user opens the popup once.

import type { PaddleSubscription } from "../definitions/global.definition";

type TrialResolver = () => Promise<PaddleSubscription | null>;

const storageGet = (
  storage: chrome.storage.StorageArea,
  keys: string[]
): Promise<Record<string, unknown>> =>
  new Promise((resolve) => storage.get(keys, (data) => resolve(data ?? {})));

const storageSet = (
  storage: chrome.storage.StorageArea,
  items: Record<string, unknown>
): Promise<void> => new Promise((resolve) => storage.set(items, () => resolve()));

/**
 * Write a guest-trial subscription to chrome.storage.local if no
 * subscription is already present. Returns whether a write occurred.
 *
 * - Existing subscription (e.g. Paddle-paid, prior trial) is left alone.
 * - Resolver returning null (trial disabled by server config) is a no-op.
 * - Resolver throwing (network failure) is swallowed — the SW must not
 *   crash on install just because the trial config fetch failed.
 */
export const bootstrapGuestTrialIfAbsent = async (
  storage: chrome.storage.StorageArea,
  resolveSubscription: TrialResolver
): Promise<boolean> => {
  try {
    const data = await storageGet(storage, ["subscription"]);
    if (data.subscription !== undefined) return false;

    const subscription = await resolveSubscription();
    if (!subscription) return false;

    await storageSet(storage, { subscription });
    return true;
  } catch {
    return false;
  }
};
