// First-install seed for chrome.storage.local. Without this, the content
// script's onStart bails when no globalSettings exists, which means the
// Cmd+F intercept never installs until the user happens to open the
// popup. Wired up from background.ts's chrome.runtime.onInstalled handler.

import { globalSettingsDefaults } from "../store/globalSettings.defaults";

// Promise wrapper over chrome.storage.local.{get,set}. We don't reuse
// chrome.utils.ts here to keep this file dependency-free — background.ts
// is a service worker entry point and pulling in popup-side helpers risks
// dragging Redux into the SW bundle.
const storageGet = (
  storage: chrome.storage.StorageArea,
  keys: string[]
): Promise<Record<string, unknown>> =>
  new Promise((resolve) => storage.get(keys, (data) => resolve(data ?? {})));

const storageSet = (
  storage: chrome.storage.StorageArea,
  items: Record<string, unknown>
): Promise<void> => new Promise((resolve) => storage.set(items, () => resolve()));

/**
 * Write globalSettingsDefaults if and only if chrome.storage.local has no
 * existing globalSettings. Returns whether a seed was performed.
 *
 * Safe to call concurrently or repeatedly: the existence check is
 * idempotent, and writing the same defaults twice is a no-op the storage
 * change listener can dedupe.
 */
export const seedDefaultsIfAbsent = async (
  storage: chrome.storage.StorageArea
): Promise<boolean> => {
  const data = await storageGet(storage, ["globalSettings"]);
  if (data.globalSettings !== undefined) return false;
  await storageSet(storage, { globalSettings: globalSettingsDefaults });
  return true;
};
