// Cross-tab search protocol. Three-leg flow:
//
//   1. Bar (content script in active tab)
//        → chrome.runtime.sendMessage({ type: CROSS_TAB_REQUEST, ... })
//   2. Background service worker
//        → chrome.tabs.query({}) → for each tab id, chrome.tabs.sendMessage
//        → aggregates responses, replies to (1) with { results }
//   3. Each tab's content script
//        → handles CROSS_TAB_PROBE locally: runs ephemeralSearch.find,
//        → returns { count, snippet, url, title }
//
// All messages here are typed so the runtime listener can discriminate by
// `type` without colliding with the popup messaging protocol.

import {
  AdHocMatch,
  AdHocSearchModifiers,
  find,
  findInsideSavedHighlights,
} from "./ephemeralSearch";

export const CROSS_TAB_REQUEST = "highlighty-cmdf-find-all";
export const CROSS_TAB_PROBE = "highlighty-cmdf-find-in-tab";
// Sent FROM background TO the single tab the user clicked in the cross-tab
// results, right after that tab is focused. Carries the searcher's term so the
// destination content script can open its finder bar pre-filled and continue
// the search there. Only ever delivered to the clicked tab.
export const OPEN_WITH_TERM = "highlighty-cmdf-open-with-term";

export interface CrossTabRequest {
  type: typeof CROSS_TAB_REQUEST;
  term: string;
  modifiers: AdHocSearchModifiers;
  // CMF-31: the "search only inside saved highlights" (H) mode is the
  // searcher's intent and must apply to every probed tab, or the cross-tab
  // counts silently use different search semantics than the in-page bar.
  // Optional for back-compat with older probes (absent → full-page find).
  searchOnlyInSavedHighlights?: boolean;
}

export interface CrossTabProbe {
  type: typeof CROSS_TAB_PROBE;
  term: string;
  modifiers: AdHocSearchModifiers;
  searchOnlyInSavedHighlights?: boolean;
}

export interface CrossTabHit {
  tabId: number;
  url: string;
  title: string;
  count: number;
  snippet: string;
}

export interface CrossTabResponse {
  results: CrossTabHit[];
}

const SNIPPET_RADIUS = 50;

/**
 * Build a short context snippet for the cross-tab preview, centred on the
 * actual match.
 *
 * CMF-11 + CMF-25: the snippet MUST be sliced from the source string the
 * match's offsets refer to — never re-located via `Element.textContent` +
 * `indexOf`. The previous implementation sliced the start node's parent
 * `textContent` and re-found the term with `indexOf(first.text)`, which
 * (a) centres on the FIRST occurrence when the matched word repeats inside
 * the parent (wrong-occurrence preview) and (b) yields `idx === -1` → a
 * garbage window anchored at the element start when the match spans a
 * text-node/block boundary (the corpus join the parent's textContent
 * doesn't contain).
 *
 * Two corpora, one slicing contract:
 *   - FIELD match (`first.field` set): the corpus is the field's own
 *     `element.value`; slice at `fieldStart … fieldEnd` (`first.range`
 *     wraps the whole field element, so its textContent is useless here —
 *     CMF-11).
 *   - RANGE match: the corpus is the `find()` result's filtered document
 *     `text`; slice at `first.start … first.end` (CMF-25). This is the
 *     documented contract in `ephemeralSearch.ts` ("Snippet previews must
 *     slice this, not Element.textContent").
 */
const buildSnippet = (first: AdHocMatch, corpusText: string): string => {
  let source: string;
  let matchStart: number;
  let matchEnd: number;
  if (first.field) {
    source = first.field.element.value ?? "";
    matchStart = first.field.fieldStart;
    matchEnd = first.field.fieldEnd;
  } else {
    source = corpusText;
    matchStart = first.start;
    matchEnd = first.end;
  }
  // Defensive clamps: offsets always lie within their source by
  // construction, but keep slice bounds sane if a source was truncated.
  matchStart = Math.max(0, Math.min(matchStart, source.length));
  matchEnd = Math.max(matchStart, Math.min(matchEnd, source.length));
  const start = Math.max(0, matchStart - SNIPPET_RADIUS);
  const end = Math.min(source.length, matchEnd + SNIPPET_RADIUS);
  return (
    (start > 0 ? "…" : "") +
    source.slice(start, end) +
    (end < source.length ? "…" : "")
  );
};

// MSG-01: a probed tab whose content script receives the probe but never
// answers (e.g. its renderer is busy/hung on a heavy synchronous task) would
// otherwise leave its probe Promise — and the Promise.all that aggregates all
// probes — pending forever, hanging the bar's "Search all tabs" spinner with
// no recovery. Cap each probe so one unresponsive tab can't poison the whole
// fan-out; a tab that doesn't answer in time is treated as "no result".
export const CROSS_TAB_PROBE_TIMEOUT_MS = 3000;

// MSG-04: the bar-side await on the CROSS_TAB_REQUEST round-trip resolves
// only inside the runtime.sendMessage callback (response or lastError). If
// the service worker is evicted mid-request, or the callback is dropped
// without firing a lastError, the await would never settle → the bar's
// "Search all tabs" spinner sticks (its `finally` never runs). Bound the
// wait so a never-answered request resolves empty instead of hanging. The
// background's own fan-out is capped at CROSS_TAB_PROBE_TIMEOUT_MS per tab,
// so a healthy SW always replies well under this ceiling; this only catches
// the SW-eviction / dropped-callback edge.
export const CROSS_TAB_REQUEST_TIMEOUT_MS = 10000;

/**
 * Per-tab handler — runs in every content script. Listens for the probe
 * message from the background script and answers with this tab's match
 * count + a snippet for the first match. Self-reports url/title so the
 * background doesn't depend on `tabs` permission for those fields.
 *
 * Returns a disposer that removes the registered listener. Callers MUST
 * invoke it during cleanup; otherwise a tab that disabled the takeover
 * keeps answering cross-tab probes from other tabs (audit bug #7 —
 * privacy regression).
 */
// Resolve the extension runtime API (chrome.* preferred, browser.* fallback),
// or null when neither is available (e.g. a non-extension test context). One
// definition so a cross-browser fix lands in a single place.
const resolveRuntimeApi = (): any =>
  typeof chrome !== "undefined" && chrome.runtime
    ? chrome.runtime
    : typeof browser !== "undefined" && browser.runtime
    ? browser.runtime
    : null;

/**
 * Install a runtime.onMessage listener that fires ONLY for `type` and ONLY from
 * the extension's own background — the CMF-27 sender gate (a web page can't
 * reach onMessage without externally_connectable, but a compromised/other
 * extension or a future forwarding path could; unvalidated senders are dropped
 * silently). `handle` runs after both gates and owns the response. One skeleton
 * so the security gate is maintained in a single place, not per handler.
 * Returns a disposer, or null when runtime messaging is unavailable.
 */
const installGatedMessageHandler = (
  type: string,
  handle: (msg: any, sender: any, sendResponse: (v: any) => void) => void
): (() => void) | null => {
  const runtimeApi = resolveRuntimeApi();
  if (!runtimeApi || !runtimeApi.onMessage) return null;

  const listener = (msg: any, sender: any, sendResponse: (v: any) => void) => {
    if (!msg || msg.type !== type) return;
    const runtimeId = runtimeApi?.id;
    if (runtimeId != null && sender?.id !== runtimeId) return;
    handle(msg, sender, sendResponse);
    // Synchronous response (or none) — never keep the channel open.
    return false;
  };

  runtimeApi.onMessage.addListener(listener);
  return () => {
    try {
      runtimeApi.onMessage.removeListener(listener);
    } catch {}
  };
};

export const installCrossTabProbeHandler = (
  // CMF-30: resolve THIS tab's own search root — the same scoped root the
  // in-page bar searches (the PDF text layer on the viewer page, where
  // `document.body` also holds the extension's own React UI chrome). Without
  // it the probe counts/snippets the viewer UI, so the cross-tab count for a
  // tab disagrees with that tab's own bar count. Falls back to document.body
  // when no scoped root is supplied (a plain page).
  resolveSearchRoot?: () => Node
): (() => void) | null =>
  // CMF-27: this probe discloses the tab's URL, title, match count and a content
  // snippet, so the shared gate answers only the extension's own background.
  installGatedMessageHandler(CROSS_TAB_PROBE, (msg, _sender, sendResponse) => {
    try {
      // CMF-30: search this tab's own scoped root (falls back to body).
      // CMF-31: honor the searcher's "saved highlights only" mode so the
      // cross-tab count uses the SAME search semantics as the in-page bar.
      const root = (() => {
        try {
          return resolveSearchRoot?.() ?? document.body;
        } catch {
          return document.body;
        }
      })();
      const searcher = msg.searchOnlyInSavedHighlights
        ? findInsideSavedHighlights
        : find;
      const { matches, text: corpusText } = searcher(
        msg.term,
        msg.modifiers,
        root
      );
      const first = matches[0];
      let snippet = "";
      if (first) {
        // CMF-11 + CMF-25: slice the snippet from the source the match's
        // offsets refer to (field value or filtered corpus), never from
        // the start node's parent textContent re-found via indexOf.
        snippet = buildSnippet(first, corpusText);
      }
      const url = (() => {
        try { return window.location.href; } catch { return ""; }
      })();
      const title = (() => {
        try { return document.title || ""; } catch { return ""; }
      })();
      sendResponse({ count: matches.length, snippet, url, title });
    } catch {
      sendResponse({ count: 0, snippet: "", url: "", title: "" });
    }
  });

/**
 * Destination-side handler for the "open the finder on the clicked tab" flow.
 * Armed once per content script (idempotent, mirrors installCrossTabProbeHandler)
 * so the tab the user jumped to can open its bar pre-filled with the searcher's
 * term. Returns a disposer, or null when runtime messaging is unavailable.
 *
 * Security: shares the probe handler's CMF-27 sender gate (see
 * installGatedMessageHandler) — the term is forwarded by our own background via
 * chrome.tabs.sendMessage, so a valid sender.id === runtime.id; a foreign sender
 * is ignored (no bar is forced open on this page).
 */
export const installOpenWithTermHandler = (
  onOpen: (term: string) => void
): (() => void) | null =>
  installGatedMessageHandler(OPEN_WITH_TERM, (msg) => {
    if (typeof msg.term === "string" && msg.term) {
      try {
        onOpen(msg.term);
      } catch {}
    }
  });

/**
 * Bar-side: ask the background to fan out the search across tabs.
 * Resolves with the aggregated results (excluding the originating tab).
 */
export const requestCrossTabSearch = async (
  term: string,
  modifiers: AdHocSearchModifiers,
  // CMF-31: forward the bar's saved-highlights-only mode so every probed tab
  // computes its count under the same search semantics as the active tab.
  searchOnlyInSavedHighlights = false
): Promise<CrossTabResponse> => {
  const runtimeApi = resolveRuntimeApi();
  if (!runtimeApi?.sendMessage) return { results: [] };
  try {
    const response: CrossTabResponse = await new Promise((resolve, reject) => {
      // MSG-04: settle at most once and always clear the guard timer, so a
      // late reply after a timeout can't double-resolve and the timer can't
      // leak.
      let done = false;
      const settle = (run: () => void) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        run();
      };
      // MSG-04: never wait forever. If the SW is evicted mid-request (no
      // response, no lastError), resolve empty so the bar's spinner clears.
      const timer = setTimeout(
        () => settle(() => resolve({ results: [] })),
        CROSS_TAB_REQUEST_TIMEOUT_MS
      );
      runtimeApi.sendMessage(
        {
          type: CROSS_TAB_REQUEST,
          term,
          modifiers,
          searchOnlyInSavedHighlights,
        } satisfies CrossTabRequest,
        (resp: CrossTabResponse | undefined) => {
          if (runtimeApi.lastError) {
            settle(() => reject(new Error(runtimeApi.lastError.message)));
            return;
          }
          settle(() => resolve(resp ?? { results: [] }));
        }
      );
    });
    return response ?? { results: [] };
  } catch {
    return { results: [] };
  }
};

/**
 * Background-side: fans out the probe to every reachable tab and
 * aggregates responses. Tabs without a matching content script reject
 * silently and are skipped.
 */
export const handleCrossTabRequest = async (
  msg: CrossTabRequest,
  originSender: any
): Promise<CrossTabResponse> => {
  const tabsApi: any =
    typeof chrome !== "undefined" && chrome.tabs
      ? chrome.tabs
      : typeof browser !== "undefined" && browser.tabs
      ? browser.tabs
      : null;
  if (!tabsApi) return { results: [] };

  const tabs: any[] = await new Promise((resolve) => {
    try {
      const maybe = tabsApi.query({}, (list: any[]) => resolve(list ?? []));
      if (maybe && typeof (maybe as any).then === "function") {
        (maybe as unknown as Promise<any[]>).then(resolve);
      }
    } catch {
      resolve([]);
    }
  });

  const probe: CrossTabProbe = {
    type: CROSS_TAB_PROBE,
    term: msg.term,
    modifiers: msg.modifiers,
    // CMF-31: pass the searcher's saved-highlights-only mode through to every
    // probed tab so their counts match the in-page bar's semantics.
    searchOnlyInSavedHighlights: msg.searchOnlyInSavedHighlights,
  };

  // CMF-40: identify the originating tab robustly. Normally sender.tab.id is
  // present and we exclude by id. But if it's absent (a non-tab / forwarded
  // sender), `tab.id === undefined` is false for every real tab → the origin
  // tab would self-list ("N other tabs" off by one). Fall back to a URL match
  // so it's still excluded; only if NEITHER id nor url is known do we probe it.
  // CMF-46: Chrome's DOCUMENTED degenerate id is chrome.tabs.TAB_ID_NONE (-1)
  // — set on apps / devtools-window senders — not nullish. A raw `!= null`
  // guard admits -1 into the id-branch, where `tab.id === -1` matches no
  // queried tab (query never returns -1) and the URL fallback never engages,
  // re-opening the CMF-40 self-list. A real tab id is a NON-NEGATIVE INTEGER;
  // accept only that shape so -1 (and any other degenerate value — NaN, a
  // fraction, a negative sentinel) falls through to the URL fallback. A real
  // id still excludes by id (a same-URL twin is kept).
  const rawOriginId = originSender?.tab?.id;
  const originId: number | undefined =
    Number.isInteger(rawOriginId) && rawOriginId >= 0 ? rawOriginId : undefined;
  const originUrl: string | undefined =
    originSender?.tab?.url ?? originSender?.url;
  const isOriginTab = (tab: any): boolean =>
    originId != null
      ? tab.id === originId
      : originUrl != null && tab.url === originUrl;

  const probes = tabs.map(async (tab): Promise<CrossTabHit | null> => {
    if (tab.id == null) return null;
    if (isOriginTab(tab)) return null;
    return new Promise<CrossTabHit | null>((resolve) => {
      // Settle at most once: whichever of the response callback, the catch,
      // or the timeout fires first wins. (Promise resolve is already
      // idempotent, but the flag lets us clear the timer deterministically.)
      let done = false;
      const finish = (hit: CrossTabHit | null) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        resolve(hit);
      };
      // MSG-01: bound the wait so an unresponsive tab can't hang the fan-out.
      const timer = setTimeout(() => finish(null), CROSS_TAB_PROBE_TIMEOUT_MS);
      try {
        tabsApi.sendMessage(tab.id!, probe, (resp: any) => {
          // chrome.runtime.lastError fires for tabs without our content script
          // (chrome://, devtools, etc.) — swallow and treat as no result.
          void chrome.runtime.lastError;
          // CMF-41: only a POSITIVE numeric count is a hit. `resp.count === 0`
          // let a reply with a missing/undefined/NaN/negative count through as
          // a hit → a blank-count row + a NaN sort comparator. `!(count > 0)`
          // rejects all of those (undefined/NaN/≤0) uniformly.
          if (!resp || !(resp.count > 0)) {
            finish(null);
            return;
          }
          finish({
            tabId: tab.id!,
            url: resp.url || tab.url || "",
            title: resp.title || tab.title || "",
            count: resp.count,
            snippet: resp.snippet || "",
          });
        });
      } catch {
        finish(null);
      }
    });
  });

  const settled = await Promise.all(probes);
  const results = settled.filter((r): r is CrossTabHit => r !== null);
  // Surface tabs with the highest counts first.
  results.sort((a, b) => b.count - a.count);
  return { results };
};

/**
 * Background entry point. Returns true when the message was ours so the
 * caller knows to keep the response channel open.
 */
export const interceptCrossTabBackgroundMessage = (
  msg: any,
  sender: any,
  sendResponse: (v: any) => void
): boolean => {
  if (!msg || msg.type !== CROSS_TAB_REQUEST) return false;
  void handleCrossTabRequest(msg, sender).then(sendResponse).catch(() => sendResponse({ results: [] }));
  return true; // async response
};
