// MSG-05: re-broadcast a content-originated settings change (e.g. the Shift+T
// extension toggle in content.switchOffHotkey) to every OTHER tab. A content
// script can't message other tabs directly, so it sends a BROADCAST_SETTINGS
// message to the background, which fans it out using the same
// { from: 0, message: { globalSettings } } envelope that the content
// receive-path (receiveMessageFromPopup → validateSender) already validates and
// applies. Without this, only the originating tab reflects the toggle; other
// open tabs keep their stale isExtensionOn (still highlighting, or still off)
// until they navigate/reload.
import { GlobalSettings } from "../../definitions/global.definition";

export const BROADCAST_SETTINGS = "highlighty-broadcast-settings";

export interface BroadcastSettingsMessage {
  type: typeof BROADCAST_SETTINGS;
  globalSettings: GlobalSettings;
}

const resolveTabsApi = (): any =>
  typeof chrome !== "undefined" && chrome.tabs
    ? chrome.tabs
    : typeof browser !== "undefined" && (browser as any).tabs
    ? (browser as any).tabs
    : null;

const resolveRuntimeApi = (): any =>
  typeof chrome !== "undefined" && chrome.runtime
    ? chrome.runtime
    : typeof browser !== "undefined" && (browser as any).runtime
    ? (browser as any).runtime
    : null;

/**
 * Background-side handler. Returns true when the message was ours (so the
 * caller stops processing it). The fan-out excludes the originating tab — it
 * already applied the change locally — and swallows per-tab errors (tabs with
 * no content script). Responds synchronously, so the caller should NOT keep the
 * message channel open.
 */
export const interceptBroadcastSettingsMessage = (
  message: any,
  sender: any,
  response: (v: any) => void
): boolean => {
  if (
    !message ||
    message.type !== BROADCAST_SETTINGS ||
    !message.globalSettings
  ) {
    return false;
  }

  const tabsApi = resolveTabsApi();
  const runtimeApi = resolveRuntimeApi();
  const senderTabId = sender?.tab?.id;

  if (tabsApi?.query) {
    try {
      tabsApi.query({}, (tabs: any[]) => {
        for (const tab of tabs ?? []) {
          if (tab?.id == null || tab.id === senderTabId) continue;
          try {
            tabsApi.sendMessage(
              tab.id,
              { from: 0, message: { globalSettings: message.globalSettings } },
              () => void runtimeApi?.lastError
            );
          } catch {
            /* tab without our content script — ignore */
          }
        }
      });
    } catch {
      /* tabs.query unavailable — best-effort */
    }
  }

  try {
    response({ success: true });
  } catch {
    /* channel already closed */
  }
  return true;
};
