// Side-effect-free defaults for GlobalSettings. Lives outside the Redux slice
// so background.ts (an MV3 service worker) can import the shape without also
// pulling @reduxjs/toolkit into the SW bundle.
//
// The Redux slice re-imports from here so popup hydration and background
// seeding stay locked to the same source of truth.

import {
  cmdFTakeoverDefaults,
  paidFeatures,
} from "../components/shared/utils/constants.consts";
import type {
  LastDeletedQueryItem,
  QueryItem,
  QueryListItem,
  QueryListState,
} from "../definitions/global.definition";

// whitelistSites and blacklistSites must be DISTINCT objects — a single shared
// reference let an in-place mutation of one list bleed into the other (and into
// the module default). A factory hands each key its own object. (STO-01)
const makeWebsiteList = () => ({ isOn: false, websiteList: "" });

// selectedList and queryList[0] must be DISTINCT objects (each with its own
// itemList array) — a single shared `queryListInit` reference let an in-place
// mutation of one be visible via the other. A factory hands each its own
// object. (STO-03)
export const makeQueryListInit = (): QueryListItem => ({
  name: "default",
  value: "default",
  id: "default",
  itemList: [] as QueryItem[],
});

const queryListState: QueryListState = {
  selectedList: makeQueryListInit(),
  queryList: [makeQueryListInit()],
};

const navigationBarInit = {
  isOn: false,
  hasWordFocus: false,
  focusedWord: null,
  assignedButtons: { upButtonKey: "W", downButtonKey: "S" },
};

export const globalSettingsDefaults = {
  isExtensionOn: true,
  queryNotFound: { isOn: true },
  queryFound: { isOn: true },
  analytics: { isOn: false },
  navigationBar: navigationBarInit,
  caseSens: { isOn: false },
  diacriticSens: { isOn: false },
  splitSearch: { isOn: false },
  completeWordSearch: { isOn: false },
  iframeSearch: { isOn: false },
  isCompactVIew: { isOn: false },
  isQueryClickInverted: { isOn: false },
  isQueryClickDisabled: { isOn: false },
  isSeachOnHotkey: { isOn: false },
  scrollbarHighlighter: { isOn: true },
  documentMinimap: { isOn: true },
  pdfEagerRender: { isOn: false },
  cmdFTakeover: cmdFTakeoverDefaults,
  formFieldHighlighting: {
    isOn: true,
    textareas: true,
    textInputs: true,
  },
  queryListState: queryListState,
  whitelistSites: makeWebsiteList(),
  blacklistSites: makeWebsiteList(),
  lastDeletedQueryItem: null as LastDeletedQueryItem | null,
  ...paidFeatures.globalSettings,
};
