import { validateSender } from "./backround.utils";
import { MessageResponse } from "./content.definitions";
import { addBadgeText } from "./features/background.sumBadge";
import { interceptCrossTabBackgroundMessage, OPEN_WITH_TERM } from "./features/cmdFTakeover/crossTab";
import { interceptBroadcastSettingsMessage } from "./features/background.broadcastSettings";
import { cmdFTakeoverDefaults } from "../components/shared/utils/constants.consts";
import { seedDefaultsIfAbsent } from "./background.seedDefaults";
import { bootstrapGuestTrialIfAbsent } from "./background.bootstrapTrial";
import { getGuestTrialSubscription } from "../components/MidPart/components/AccountTab/trial.utils";
import { seedMonotonicClock } from "../components/shared/utils/monotonicClock.utils";

chrome.runtime.onInstalled.addListener(() => {
  // Seed default globalSettings on first install so the content script's
  // Cmd+F intercept arms without requiring the user to open the popup
  // first. Both seeds are idempotent — they no-op when their respective
  // storage keys already exist, so existing users on update keep their data.
  void seedDefaultsIfAbsent(chrome.storage.local);

  // SUB-26: seed the monotonic high-water clock BEFORE the trial bootstrap —
  // `getGuestTrialSubscription` builds/validates the trial via `monotonicNow()`,
  // and this background service worker never otherwise seeds, so without this it
  // would fall back to raw `Date.now()` and bypass the SUB-09 rollback defense
  // in the background context (and an unseeded `monotonicNow` is gated from
  // persisting, so the bootstrap must seed first to anchor the mark).
  void (async () => {
    await seedMonotonicClock();
    // Bootstrap the guest-trial subscription so the freemium converter sees
    // an active trial on the first content-script run. Without this, the
    // Cmd+F bar shows free-tier modifiers only until the popup is opened.
    await bootstrapGuestTrialIfAbsent(chrome.storage.local, () =>
      getGuestTrialSubscription(true)
    );
  })();
});

// MSG-03: the per-tab badge ("N" matches) is set only by a tab's content
// script and cleared only by that same content script. If a tab showing "12"
// navigates to a URL where the content script never runs (chrome://, the Web
// Store, extension/restricted pages), no cleanup fires and the stale "12"
// lingers. Reset the per-tab badge on a real same-tab navigation so the count
// can't outlive the page that produced it; a content script that DOES run on
// the new page simply re-sets its own count afterwards.
export const clearBadgeOnNavigation = (
  tabId: number,
  changeInfo: chrome.tabs.TabChangeInfo
) => {
  // Only act on a genuine top-level navigation (a new committed URL), not on
  // every loading/complete status tick — those don't change the page identity.
  if (changeInfo?.url == null) return;
  if (
    !chrome?.action ||
    !chrome?.action?.setBadgeText ||
    tabId == null
  )
    return;
  try {
    chrome.action.setBadgeText({ text: "", tabId }, () => {
      void chrome.runtime.lastError;
    });
  } catch {}
};

if (chrome.tabs?.onUpdated?.addListener) {
  chrome.tabs.onUpdated.addListener(clearBadgeOnNavigation);
}

// Kill-switch chord (Cmd+Shift+F / Ctrl+Shift+F). Bound at the browser
// level via the manifest "commands" block — survives content-script
// failures, page CSP, anything below the browser. Toggles
// cmdFTakeover.isOn in storage; the next intercept install/uninstall
// cycle picks it up via the existing storage listener.
export const handleKillSwitch = async () => {
  try {
    // MSG-02: the get→modify→set is a read-modify-write of the WHOLE
    // globalSettings blob, so a concurrent writer (popup/content) landing
    // between our read and write would be clobbered (last-writer-wins). Harden
    // to a single-writer re-read: inside the set callback, re-read storage and
    // only keep going if the value we wrote is still the value on disk. If a
    // concurrent writer raced us, we DO NOT broadcast our (now-stale) blob —
    // we let their write (and its own broadcast) win, avoiding the clobber's
    // visible fan-out.
    chrome.storage.local.get(["globalSettings"], (data) => {
      const cur = data?.globalSettings ?? {};
      const cmdF = { ...cmdFTakeoverDefaults, ...(cur.cmdFTakeover ?? {}) };
      const next = {
        ...cur,
        cmdFTakeover: { ...cmdF, isOn: !cmdF.isOn },
      };
      chrome.storage.local.set({ globalSettings: next }, () => {
        // MSG-10: bail before broadcasting if the persist itself failed
        // (quota, corruption, SW teardown). Without this gate a failed write
        // still fans `next` out to every tab, so live tabs would reflect a
        // toggle that storage never kept — a divergence that reverts on
        // reload. A failed persist must not reach any tab.
        if (chrome.runtime.lastError) return;

        // MSG-02 single-writer re-read: confirm our write is still the
        // canonical value before broadcasting. If a concurrent writer
        // overwrote `globalSettings` between our set's enqueue and its
        // completion, the on-disk cmdFTakeover.isOn won't match ours; in that
        // case we yield to the concurrent writer and skip our broadcast.
        chrome.storage.local.get(["globalSettings"], (after) => {
          if (chrome.runtime.lastError) return;
          const persisted = after?.globalSettings;
          if (
            !persisted ||
            persisted.cmdFTakeover?.isOn !== next.cmdFTakeover.isOn
          ) {
            // A concurrent writer won the race — don't broadcast our stale blob.
            return;
          }

          // Broadcast to all tabs so live content scripts pick up the change
          // without a navigation. Errors per tab (no content script) are
          // expected and silently ignored.
          chrome.tabs.query({}, (tabs) => {
            for (const tab of tabs) {
              if (tab.id == null) continue;
              try {
                chrome.tabs.sendMessage(
                  tab.id,
                  { from: 0, message: { globalSettings: persisted } },
                  () => void chrome.runtime.lastError
                );
              } catch {}
            }
          });
        });
      });
    });
  } catch {}
};

if (chrome.commands?.onCommand) {
  chrome.commands.onCommand.addListener((command) => {
    if (command === "cmdf_kill_switch") {
      void handleKillSwitch();
    }
  });
}

// MSG-07: defense-in-depth — only act on messages from our OWN extension
// context. `onMessage` only ever sees same-extension senders today (no
// `externally_connectable`), so this is latent hardening: it ensures the early
// cross-tab / broadcast / focus-tab handlers below can never fan a forged blob
// out to every tab if a content-script context were ever compromised. Mirrors
// the badge path's `validateSender` sender-id check. Lenient when the runtime
// id is unavailable (test/edge harnesses) so the happy path is unaffected.
const isOwnExtensionSender = (
  sender: chrome.runtime.MessageSender
): boolean => {
  const runtimeId = (chrome ?? browser)?.runtime?.id;
  // If we can't determine our own id, don't gate (preserve existing behaviour).
  if (runtimeId == null) return true;
  return sender?.id === runtimeId;
};

export const handleRuntimeMessage = (
  message: any,
  sender: chrome.runtime.MessageSender,
  response: MessageResponse
): boolean | undefined => {
    // MSG-07: gate the three early cross-tab/background handlers behind a
    // same-extension sender check before acting on them.
    const ownSender = isOwnExtensionSender(sender);

    // Cmd+F cross-tab fan-out runs first because it returns true to keep
    // the response channel open async; the existing badge handler is
    // synchronous and shouldn't see it.
    if (ownSender && interceptCrossTabBackgroundMessage(message, sender, response)) {
      return true;
    }

    // MSG-05: re-broadcast a content-originated settings change (the Shift+T
    // extension toggle) to all OTHER tabs. Synchronous response → don't keep
    // the channel open.
    if (ownSender && interceptBroadcastSettingsMessage(message, sender, response)) {
      return false;
    }

    // Bar → background → focus a matched tab from cross-tab results.
    if (ownSender && message?.type === "highlighty-cmdf-focus-tab" && typeof message.tabId === "number") {
      try {
        const tabsApi: any =
          typeof chrome !== "undefined" && chrome.tabs
            ? chrome.tabs
            : typeof browser !== "undefined" && browser.tabs
            ? browser.tabs
            : null;
        tabsApi?.update?.(message.tabId, { active: true });
        // Also focus the window the tab lives in (chrome.windows.update).
        // Best-effort: skip if window context isn't available.
        tabsApi?.get?.(message.tabId, (tab: any) => {
          void chrome.runtime.lastError;
          if (tab?.windowId != null && chrome.windows?.update) {
            chrome.windows.update(tab.windowId, { focused: true });
          }
        });
        // If the click carried a search term, tell ONLY that clicked tab to
        // open its finder pre-filled so the user can continue searching there.
        // Fire-and-forget: a discarded/reloading tab may miss it (its content
        // script re-boots), which is acceptable — the tab is still focused.
        if (typeof message.openTerm === "string" && message.openTerm) {
          try {
            tabsApi?.sendMessage?.(
              message.tabId,
              { type: OPEN_WITH_TERM, term: message.openTerm },
              () => { void chrome.runtime.lastError; }
            );
          } catch {}
        }
      } catch {}
      try { response({ success: true }); } catch {}
      return false;
    }

    // OPEN_PDF_IN_WORKSPACE is owned by PdfApp's runtime listener — it
    // returns true and answers asynchronously after loadRemotePdf settles.
    // The catch-all `response({ success: true })` below would otherwise
    // beat that async answer (sync wins, first call delivered), making
    // routePdfToWorkspace falsely resolve "success" even when no PDF
    // Search tab is mounted. Bail out here so PdfApp owns the response.
    if (message?.type === "OPEN_PDF_IN_WORKSPACE") {
      return false;
    }

    const isValidated = validateSender(message, sender);

    if (isValidated) {
      addBadgeText(message?.message, sender.tab?.id);
    }

    try {
      response({ success: true });
      // console.log("✅ Response sent!");
    } catch (error) {
      console.error("❌ Error in background.ts messaging:", error);
      response({ success: false, error: (error as any).message });
    }

    return undefined;
};

(chrome ?? browser).runtime?.onMessage?.addListener(handleRuntimeMessage);
