import {
  getStorageData,
  getStorageDataLocal,
  setStorageData,
  setStorageDataLocal,
} from "../../../../chrome/chrome.utils";
import { monotonicNow } from "../../../shared/utils/monotonicClock.utils";
import { PaddleSubscription } from "../../../../definitions/global.definition";

export interface PublicTrialConfig {
  guestTrialEnabled: boolean;
  guestTrialDays: number;
  registeredTrialDays: number;
  updatedAt: string | null;
  cacheTtlSeconds: number;
}

interface CachedPublicTrialConfig {
  config: PublicTrialConfig;
  fetchedAt: number;
}

interface GuestTrialState {
  initializedAt: string;
  guestTrialStartedAt: string | null;
  guestTrialEndsAt: string | null;
  guestTrialDaysSnapshot: number;
  guestTrialConfigVersion: string | null;
  guestTrialDisabledByConfigAt: string | null;
}

interface LocalTrialStackState {
  uid: string;
  guestBonusMs: number;
  appTrialStartedAt: string | null;
  originalAppTrialEndsAt: string | null;
  stackedTrialEndsAt: string;
  createdAt: string;
}

const PUBLIC_TRIAL_CONFIG_KEY = "publicTrialConfig";
const GUEST_TRIAL_STATE_KEY = "guestTrialState";
const LOCAL_TRIAL_STACKS_KEY = "localTrialStacks";

const DEFAULT_PUBLIC_TRIAL_CONFIG: PublicTrialConfig = {
  guestTrialEnabled: true,
  guestTrialDays: 2,
  registeredTrialDays: 5,
  updatedAt: null,
  cacheTtlSeconds: 300,
};

const toIsoNow = () => new Date().toISOString();

const addDays = (date: Date, days: number) => {
  const nextDate = new Date(date);
  nextDate.setDate(nextDate.getDate() + Math.max(days, 0));
  return nextDate;
};

const normalizePositiveInteger = (value: unknown, fallback: number) => {
  if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
    return Math.floor(value);
  }

  if (typeof value === "string") {
    const parsed = Number.parseInt(value, 10);
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed;
    }
  }

  return fallback;
};

const normalizePublicTrialConfig = (value: unknown): PublicTrialConfig => {
  const config = (value ?? {}) as Partial<PublicTrialConfig>;

  return {
    guestTrialEnabled:
      typeof config.guestTrialEnabled === "boolean"
        ? config.guestTrialEnabled
        : DEFAULT_PUBLIC_TRIAL_CONFIG.guestTrialEnabled,
    guestTrialDays: normalizePositiveInteger(
      config.guestTrialDays,
      DEFAULT_PUBLIC_TRIAL_CONFIG.guestTrialDays
    ),
    registeredTrialDays: normalizePositiveInteger(
      config.registeredTrialDays,
      DEFAULT_PUBLIC_TRIAL_CONFIG.registeredTrialDays
    ),
    updatedAt:
      typeof config.updatedAt === "string" && config.updatedAt.trim().length
        ? config.updatedAt
        : DEFAULT_PUBLIC_TRIAL_CONFIG.updatedAt,
    cacheTtlSeconds: normalizePositiveInteger(
      config.cacheTtlSeconds,
      DEFAULT_PUBLIC_TRIAL_CONFIG.cacheTtlSeconds
    ),
  };
};

const loadCachedPublicTrialConfig = async (): Promise<CachedPublicTrialConfig | null> => {
  const storage = await getStorageDataLocal<{
    publicTrialConfig?: CachedPublicTrialConfig;
  }>(PUBLIC_TRIAL_CONFIG_KEY);

  const cachedPublicTrialConfig = storage?.publicTrialConfig;
  if (!cachedPublicTrialConfig?.config || !cachedPublicTrialConfig?.fetchedAt) {
    return null;
  }

  return {
    config: normalizePublicTrialConfig(cachedPublicTrialConfig.config),
    fetchedAt: cachedPublicTrialConfig.fetchedAt,
  };
};

const saveCachedPublicTrialConfig = async (config: PublicTrialConfig) => {
  await setStorageDataLocal<CachedPublicTrialConfig>({
    [PUBLIC_TRIAL_CONFIG_KEY]: {
      config,
      fetchedAt: Date.now(),
    },
  });
};

const loadGuestTrialState = async (): Promise<GuestTrialState | null> => {
  const syncStorage = await getStorageData<{
    guestTrialState?: GuestTrialState;
  }>(GUEST_TRIAL_STATE_KEY);

  return syncStorage?.guestTrialState ?? null;
};

const saveGuestTrialState = async (guestTrialState: GuestTrialState) => {
  const syncWrite = setStorageData<GuestTrialState>({
    [GUEST_TRIAL_STATE_KEY]: guestTrialState,
  });

  if (!syncWrite) {
    throw new Error("Sync storage is not available.");
  }

  await syncWrite;
};

const loadLocalTrialStacks = async (): Promise<
  Record<string, LocalTrialStackState>
> => {
  const storage = await getStorageDataLocal<{
    localTrialStacks?: Record<string, LocalTrialStackState>;
  }>(LOCAL_TRIAL_STACKS_KEY);

  return storage?.localTrialStacks ?? {};
};

const saveLocalTrialStacks = async (
  localTrialStacks: Record<string, LocalTrialStackState>
) => {
  await setStorageDataLocal<Record<string, LocalTrialStackState>>({
    [LOCAL_TRIAL_STACKS_KEY]: localTrialStacks,
  });
};

const buildGuestTrialSubscription = (
  guestTrialState: GuestTrialState
): PaddleSubscription | null => {
  if (!guestTrialState.guestTrialStartedAt || !guestTrialState.guestTrialEndsAt) {
    return null;
  }

  const trialEndDate = new Date(guestTrialState.guestTrialEndsAt);
  // SUB-10: treat the exact expiry instant as expired (`<=`), consistent with
  // the disable path's `> Date.now()` guard, so the trial isn't built ACTIVE
  // for the boundary tick.
  // SUB-09: compare against the monotonic high-water clock, not raw Date.now(),
  // so rolling the system clock back past the trial end can't rebuild the trial
  // as ACTIVE once real time has already passed it.
  if (
    Number.isNaN(trialEndDate.getTime()) ||
    trialEndDate.getTime() <= monotonicNow()
  ) {
    return null;
  }

  return {
    currentPeriodStart: guestTrialState.guestTrialStartedAt,
    currentPeriodEnd: guestTrialState.guestTrialEndsAt,
    isActive: true,
    timeStamp: new Date().toString(),
    cancelUrl: null,
    updateUrl: null,
    subscriptionStatus: "trialing",
    isCanceled: false,
    isPaddle: false,
    accessSource: "guest_trial",
  };
};

const createGuestTrialState = (
  publicTrialConfig: PublicTrialConfig
): GuestTrialState => {
  const now = new Date();
  const initializedAt = now.toISOString();

  if (!publicTrialConfig.guestTrialEnabled || publicTrialConfig.guestTrialDays <= 0) {
    return {
      initializedAt,
      guestTrialStartedAt: null,
      guestTrialEndsAt: null,
      guestTrialDaysSnapshot: 0,
      guestTrialConfigVersion: publicTrialConfig.updatedAt,
      guestTrialDisabledByConfigAt: publicTrialConfig.guestTrialEnabled
        ? null
        : initializedAt,
    };
  }

  return {
    initializedAt,
    guestTrialStartedAt: initializedAt,
    guestTrialEndsAt: addDays(now, publicTrialConfig.guestTrialDays).toISOString(),
    guestTrialDaysSnapshot: publicTrialConfig.guestTrialDays,
    guestTrialConfigVersion: publicTrialConfig.updatedAt,
    guestTrialDisabledByConfigAt: null,
  };
};

const disableGuestTrialState = (
  guestTrialState: GuestTrialState
): GuestTrialState => {
  if (guestTrialState.guestTrialDisabledByConfigAt) {
    return guestTrialState;
  }

  const disabledAt = toIsoNow();
  const activeEndDate = guestTrialState.guestTrialEndsAt
    ? new Date(guestTrialState.guestTrialEndsAt)
    : null;

  return {
    ...guestTrialState,
    guestTrialEndsAt:
      activeEndDate && activeEndDate.getTime() > Date.now()
        ? disabledAt
        : guestTrialState.guestTrialEndsAt,
    guestTrialDisabledByConfigAt: disabledAt,
  };
};

export async function getPublicTrialConfig(
  forceRefresh = false
): Promise<PublicTrialConfig> {
  const cachedConfig = await loadCachedPublicTrialConfig();

  if (!forceRefresh && cachedConfig) {
    const cacheAgeInSeconds = (Date.now() - cachedConfig.fetchedAt) / 1000;
    if (cacheAgeInSeconds < cachedConfig.config.cacheTtlSeconds) {
      return cachedConfig.config;
    }
  }

  try {
    const response = await fetch(
      `${process.env.REACT_APP_FIREBASE_DOMAIN}/getPublicConfig`
    );
    const config = normalizePublicTrialConfig(await response.json());
    await saveCachedPublicTrialConfig(config);
    return config;
  } catch (error) {
    if (cachedConfig) {
      return cachedConfig.config;
    }

    return DEFAULT_PUBLIC_TRIAL_CONFIG;
  }
}

export async function resolveGuestTrialSubscription(
  forceRefreshConfig = false
): Promise<{
  config: PublicTrialConfig;
  subscription: PaddleSubscription | null;
}> {
  const config = await getPublicTrialConfig(forceRefreshConfig);
  let guestTrialState = await loadGuestTrialState();

  if (!guestTrialState) {
    guestTrialState = createGuestTrialState(config);
    await saveGuestTrialState(guestTrialState);
  }

  if (!config.guestTrialEnabled) {
    const disabledGuestTrialState = disableGuestTrialState(guestTrialState);
    if (
      disabledGuestTrialState.guestTrialDisabledByConfigAt !==
      guestTrialState.guestTrialDisabledByConfigAt
    ) {
      await saveGuestTrialState(disabledGuestTrialState);
    }

    return {
      config,
      subscription: null,
    };
  }

  if (guestTrialState.guestTrialDisabledByConfigAt) {
    return {
      config,
      subscription: null,
    };
  }

  return {
    config,
    subscription: buildGuestTrialSubscription(guestTrialState),
  };
}

export async function getGuestTrialSubscription(forceRefreshConfig = false) {
  const { subscription } = await resolveGuestTrialSubscription(forceRefreshConfig);
  return subscription;
}

function buildLocalAppTrialSubscription(
  localTrialStackState: LocalTrialStackState
): PaddleSubscription | null {
  const stackedTrialEndDate = new Date(localTrialStackState.stackedTrialEndsAt);
  // SUB-10: `<=` so the exact expiry instant counts as expired here too,
  // matching buildGuestTrialSubscription and the disable path.
  // SUB-09: monotonic high-water clock (see buildGuestTrialSubscription) so a
  // backward clock jump can't resurrect an already-lapsed stacked app trial.
  if (
    Number.isNaN(stackedTrialEndDate.getTime()) ||
    stackedTrialEndDate.getTime() <= monotonicNow()
  ) {
    return null;
  }

  return {
    currentPeriodStart: localTrialStackState.appTrialStartedAt,
    currentPeriodEnd: localTrialStackState.stackedTrialEndsAt,
    isActive: true,
    timeStamp: new Date().toString(),
    cancelUrl: null,
    updateUrl: null,
    subscriptionStatus: "trialing",
    isCanceled: false,
    isPaddle: false,
    accessSource: "app_trial",
  };
}

function isFreeSubscription(subscription: PaddleSubscription | null) {
  return (
    Boolean(subscription) &&
    !subscription?.isPaddle &&
    subscription?.accessSource === "free" &&
    subscription?.subscriptionStatus === "unpaid"
  );
}

function isRemoteAppTrial(subscription: PaddleSubscription | null) {
  return (
    Boolean(subscription) &&
    !subscription?.isPaddle &&
    subscription?.accessSource === "app_trial" &&
    subscription?.subscriptionStatus === "trialing"
  );
}

export async function applyLocalTrialStacking(
  uid: string,
  subscription: PaddleSubscription | null
): Promise<PaddleSubscription | null> {
  if (!uid) {
    return subscription;
  }

  const localTrialStacks = await loadLocalTrialStacks();
  const existingStack = localTrialStacks[uid];
  const stackedSubscription = existingStack
    ? buildLocalAppTrialSubscription(existingStack)
    : null;

  if (existingStack && !stackedSubscription) {
    delete localTrialStacks[uid];
    await saveLocalTrialStacks(localTrialStacks);
  }

  if (subscription?.isPaddle) {
    return subscription;
  }

  if (isRemoteAppTrial(subscription)) {
    if (stackedSubscription) {
      return stackedSubscription;
    }

    const guestTrialSubscription = await getGuestTrialSubscription();
    const guestTrialEndTimestamp = guestTrialSubscription?.currentPeriodEnd
      ? new Date(guestTrialSubscription.currentPeriodEnd).getTime()
      : NaN;
    const guestTrialRemainingMs = Number.isNaN(guestTrialEndTimestamp)
      ? 0
      : Math.max(guestTrialEndTimestamp - Date.now(), 0);

    if (!guestTrialRemainingMs || !subscription?.currentPeriodEnd) {
      return subscription;
    }

    const remoteTrialEndTimestamp = new Date(
      subscription.currentPeriodEnd
    ).getTime();

    if (Number.isNaN(remoteTrialEndTimestamp)) {
      return subscription;
    }

    const stackedTrialEndsAt = new Date(
      remoteTrialEndTimestamp + guestTrialRemainingMs
    ).toISOString();

    const nextLocalTrialStackState: LocalTrialStackState = {
      uid,
      guestBonusMs: guestTrialRemainingMs,
      appTrialStartedAt: subscription.currentPeriodStart ?? null,
      originalAppTrialEndsAt: subscription.currentPeriodEnd,
      stackedTrialEndsAt,
      createdAt: new Date().toISOString(),
    };

    localTrialStacks[uid] = nextLocalTrialStackState;
    await saveLocalTrialStacks(localTrialStacks);

    return {
      ...subscription,
      currentPeriodEnd: stackedTrialEndsAt,
    };
  }

  if (isFreeSubscription(subscription) && stackedSubscription) {
    return stackedSubscription;
  }

  return subscription;
}
