import { ChromeMessage, ReactMessage, Sender } from "../types";

export interface BrowserTabInfo {
  id: number | null;
  title: string;
  url: string;
  isPdf: boolean;
  isLocalFile: boolean;
}

export interface PdfWorkspaceRoutingState {
  lastActiveWorkspaceId: string | null;
  lastActiveViewerTabId?: number | null;
}

export interface OpenPdfInWorkspaceMessage {
  type: "OPEN_PDF_IN_WORKSPACE";
  workspaceId: string;
  src: string;
}

const PDF_WORKSPACE_ROUTING_STORAGE_KEY = "pdfWorkspaceRoutingState";

export const getStorageData = <TResponse>(
  key: string
): Promise<TResponse> | undefined => {
  if (typeof browser !== "undefined" && browser.storage.sync) {
    return new Promise((resolve, reject) => {
      browser.storage.sync.get(key).then(
        (result: any) => {
          resolve(result as TResponse);
        },
        (error: any) => reject(Error(error.message))
      );
    });
  } else if (typeof chrome !== "undefined" && chrome.storage?.sync) {
    return new Promise((resolve, reject) => {
      chrome.storage.sync.get(key, (result: any) =>
        chrome.runtime.lastError
          ? reject(Error(chrome.runtime.lastError.message))
          : resolve(result as TResponse)
      );
    });
  } else {
    return undefined;
  }
};

export const setStorageData = <TData>(data: Record<string, TData>) => {
  if (typeof browser !== "undefined" && browser.storage.sync) {
    return new Promise<void>((resolve, reject) => {
      browser.storage.sync.set(data).then(
        () => resolve(),
        (error: any) => reject(Error(error.message))
      );
    });
  } else if (typeof chrome !== "undefined" && chrome.storage?.sync) {
    return new Promise<void>((resolve, reject) => {
      chrome.storage.sync.set(data, () =>
        chrome.runtime.lastError
          ? reject(Error(chrome.runtime.lastError.message))
          : resolve()
      );
    });
  } else {
    return undefined;
  }
};

