export const sendToTab = <TMessage>(messageValue: TMessage) => {
  if (
    (typeof chrome !== "undefined" && chrome.tabs) ||
    (typeof browser !== "undefined" && browser.tabs)
  ) {
    const tabsAPI = typeof chrome !== "undefined" ? chrome.tabs : browser.tabs;
    tabsAPI.query(
      {
        active: true,
        currentWindow: true,
      },
      function (tabs) {
        const message: ChromeMessage = {
          from: Sender.React,
          message: messageValue,
        };

        if (tabs[0]?.id) tabsAPI.sendMessage(tabs[0].id as number, message);
      }
    );
  }
};
export const sendToAllTabs = <TMessage>(messageValue: TMessage) => {
  if (
    (typeof chrome !== "undefined" && chrome.tabs) ||
    (typeof browser !== "undefined" && browser.tabs)
  ) {
    const tabsAPI = typeof chrome !== "undefined" ? chrome.tabs : browser.tabs;
    tabsAPI.query({}, function (tabs) {
      const message = {
        from: Sender.React,
        message: messageValue,
      };

      for (let i = 0; i < tabs.length; ++i) {
        if (tabs[i]?.id) {
          tabsAPI.sendMessage(tabs[i]?.id as number, message, () => {});
        }
      }
    });
  }
};

export const sendMessageTo = <TResponse>(messageValue: ReactMessage) => {
  if (
    (typeof chrome !== "undefined" && chrome.runtime.sendMessage) ||
    (typeof browser !== "undefined" && browser.runtime.sendMessage)
  ) {
    const runtimeAPI =
      typeof chrome !== "undefined" ? chrome.runtime : browser.runtime;

    if (typeof chrome !== "undefined") {
      return new Promise<TResponse>((resolve, reject) => {
        chrome.runtime.sendMessage(messageValue, (response: TResponse) => {
          if (runtimeAPI.lastError) {
            reject(Error(runtimeAPI.lastError.message));
          } else {
            resolve(response);
          }
        });
      });
    } else {
      return new Promise<TResponse>((resolve, reject) => {
        browser.runtime.sendMessage("", messageValue);
      });
    }
  } else {
    return undefined;
  }
};

export const isPdfUrl = (url?: string | null) => {
  if (!url) return false;

  try {
    const parsedUrl = new URL(url);
    return /\.pdf(?:$|[?#])/i.test(parsedUrl.pathname + parsedUrl.search);
  } catch {
    return /\.pdf(?:$|[?#])/i.test(url);
  }
};

export const getActiveTabInfo = (): Promise<BrowserTabInfo> => {
  if (
    !(
      (typeof chrome !== "undefined" && chrome.tabs) ||
      (typeof browser !== "undefined" && browser.tabs)
    )
  ) {
    return Promise.resolve({
      id: null,
      title: "",
      url: "",
      isPdf: false,
      isLocalFile: false,
    });
  }

  const tabsAPI = typeof chrome !== "undefined" ? chrome.tabs : browser.tabs;

  return new Promise((resolve, reject) => {
    tabsAPI.query(
      {
        active: true,
        currentWindow: true,
      },
      (tabs: chrome.tabs.Tab[]) => {
        const runtimeApi =
          typeof chrome !== "undefined" ? chrome.runtime : browser.runtime;

        if (runtimeApi?.lastError) {
          reject(Error(runtimeApi.lastError.message));
          return;
        }

        const activeTab = tabs?.[0];
        const url = activeTab?.url || "";

        resolve({
          id: activeTab?.id ?? null,
          title: activeTab?.title || "",
          url,
          isPdf: isPdfUrl(url),
          isLocalFile: url.startsWith("file://"),
        });
      }
    );
  });
};

export const buildPdfViewerUrl = (options?: {
  src?: string;
  workspaceId?: string;
}) => {
  const runtimeApi =
    typeof chrome !== "undefined" ? chrome.runtime : browser.runtime;
  const baseUrl = runtimeApi.getURL("pdf-viewer.html");
  const workspaceId = options?.workspaceId || createPdfWorkspaceId();

  const url = new URL(baseUrl);
  url.searchParams.set("workspace", workspaceId);

  if (options?.src) {
    url.searchParams.set("src", options.src);
  }

  return url.toString();
};

export const createPdfWorkspaceId = () =>
  `pdfws_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

export const getPdfWorkspaceIdFromUrl = (url?: string | null) => {
  if (!url) return null;

  try {
    return new URL(url).searchParams.get("workspace");
  } catch {
    return null;
  }
};

export const getPdfWorkspaceRoutingState = async () => {
  const data = await getStorageDataLocal<{
    [PDF_WORKSPACE_ROUTING_STORAGE_KEY]?: PdfWorkspaceRoutingState;
  }>(PDF_WORKSPACE_ROUTING_STORAGE_KEY);

  return (
    data?.[PDF_WORKSPACE_ROUTING_STORAGE_KEY] || {
      lastActiveWorkspaceId: null,
      lastActiveViewerTabId: null,
    }
  );
};

export const setLastActivePdfWorkspaceId = async (
  workspaceId: string | null,
  viewerTabId?: number | null
) => {
  await setStorageDataLocal({
    [PDF_WORKSPACE_ROUTING_STORAGE_KEY]: {
      lastActiveWorkspaceId: workspaceId,
      lastActiveViewerTabId: viewerTabId ?? null,
    },
  });
};

export const routePdfToWorkspace = async (workspaceId: string, src: string) => {
  const message = {
    type: "OPEN_PDF_IN_WORKSPACE",
    workspaceId,
    src,
  } satisfies OpenPdfInWorkspaceMessage;

  if (typeof chrome !== "undefined" && chrome.runtime?.sendMessage) {
    return new Promise<void>((resolve, reject) => {
      chrome.runtime.sendMessage(
        message,
        (response: { success?: boolean } | undefined) => {
          if (chrome.runtime.lastError) {
            reject(Error(chrome.runtime.lastError.message));
            return;
          }

          if (!response?.success) {
            reject(Error("No PDF Search workspace accepted the document."));
            return;
          }

          resolve();
        }
      );
    });
  }

  if (typeof browser !== "undefined" && browser.runtime?.sendMessage) {
    const response = await browser.runtime.sendMessage(message);

    if (!response?.success) {
      throw Error("No PDF Search workspace accepted the document.");
    }

    return;
  }

  throw Error("Runtime messaging is not available.");
};

export const openPdfInPreferredViewer = async (options: {
  src?: string;
  forceNewViewer?: boolean;
}) => {
  const routingState = await getPdfWorkspaceRoutingState();

  if (options.forceNewViewer) {
    await openPdfViewer({ src: options.src });
    return;
  }

  if (!options.src) {
    if (
      typeof routingState.lastActiveViewerTabId === "number" &&
      ((typeof chrome !== "undefined" && chrome.tabs) ||
        (typeof browser !== "undefined" && browser.tabs))
    ) {
      try {
        if (typeof chrome !== "undefined" && chrome.tabs?.update) {
          await chrome.tabs.update(routingState.lastActiveViewerTabId, {
            active: true,
          });
          return;
        }

        if (typeof browser !== "undefined" && browser.tabs?.update) {
          await browser.tabs.update(routingState.lastActiveViewerTabId, {
            active: true,
          });
          return;
        }
      } catch {}
    }

    await openPdfViewer();
    return;
  }

  if (routingState.lastActiveWorkspaceId) {
    try {
      await routePdfToWorkspace(routingState.lastActiveWorkspaceId, options.src);

      if (
        typeof routingState.lastActiveViewerTabId === "number" &&
        ((typeof chrome !== "undefined" && chrome.tabs) ||
          (typeof browser !== "undefined" && browser.tabs))
      ) {
        try {
          if (typeof chrome !== "undefined" && chrome.tabs?.update) {
            await chrome.tabs.update(routingState.lastActiveViewerTabId, {
              active: true,
            });
          } else if (typeof browser !== "undefined" && browser.tabs?.update) {
            await browser.tabs.update(routingState.lastActiveViewerTabId, {
              active: true,
            });
          }
        } catch {}
      }

      return;
    } catch {}
  }

  await openPdfViewer({
    src: options.src,
  });
};

export const openPdfViewer = async (options?: {
  src?: string;
  workspaceId?: string;
}) => {
  if (
    !(
      (typeof chrome !== "undefined" && chrome.tabs) ||
      (typeof browser !== "undefined" && browser.tabs)
    )
  ) {
    return;
  }

  const tabsAPI = typeof chrome !== "undefined" ? chrome.tabs : browser.tabs;

  await tabsAPI.create({
    active: true,
    url: buildPdfViewerUrl(options),
  });
};
