// Ad-hoc search engine. Walks visible text nodes once, builds a flat
// concatenated text string with an index → (node, localOffset) map, runs
// the chosen matcher against it, then converts each [start, end) hit back
// into a DOM Range. Returned ranges are consumed by paintAdHoc to draw
// highlights via the CSS Custom Highlight API.
//
// Three matching modes:
//   - plain   — uses the same normalization as queryMatching.ts (case /
//               diacritic / whole-word toggles)
//   - regex   — compiles the term as RegExp; on syntax error, returns []
//   - fuzzy   — bounded Levenshtein per-word; threshold scales with the
//               query length so 4-char queries tolerate 1 edit, 8-char
//               queries tolerate 2, etc.
//
// Skipped subtrees:
//   - <script>, <style>, <noscript>
//   - any element with attribute data-highlighty-cmdf or data-highlighty-adhoc
//     (so we don't recurse into our own UI or our own ephemeral DOM fallback)
//   - <select> and contenteditable surfaces — typing in those should not light
//     up our ad-hoc highlight under the cursor
//   - the bar's shadow host
//
// Searched-but-special: <input> (text-like types) and <textarea> values.
// Their text is not in the DOM as child text nodes; the walker treats them
// as leaves and emits a synthetic FieldRun keyed off element.value so the
// bar can count and navigate matches inside form fields.

import {
  isWordBoundary,
  normalizeSearchTextWithMap,
  compileWholeWordRegex,
} from "../../../search/normalization";
import { advanceRegexIndex } from "../../../search/regexExec";
import { isLikelyCatastrophic } from "../utils/regexSafety";

// Once-per-session memo so a repeated Cmd+F over the same catastrophic pattern
// logs a single warning instead of spamming the console. (QRX-04)
const warnedCatastrophicCmdFPatterns = new Set<string>();

export interface AdHocSearchModifiers {
  caseSensitive: boolean;
  wholeWord: boolean;
  diacriticSensitive: boolean;
  regex: boolean;
  fuzzy: boolean;
}

// Match landed inside an <input> or <textarea> value rather than a real
// DOM text node. Downstream code (scroll-to-match, fallback DOM painter,
// scrollbar markers) branches on this — we can't paint inside the field
// via the CSS Custom Highlight API (it walks DOM text only), but we can
// scroll the field into view and setSelectionRange to highlight the
// matched substring inside the field itself.
export interface AdHocFieldDescriptor {
  element: HTMLInputElement | HTMLTextAreaElement;
  /** Offset within `element.value` where the match starts. */
  fieldStart: number;
  /** Exclusive end offset within `element.value`. */
  fieldEnd: number;
}

export interface AdHocMatch {
  // For text-node matches, an exact Range over the matched text.
  // For field matches, a synthetic Range that wraps the field element so
  // existing consumers (scrollbar bucket rects, snippet ancestor lookups)
  // keep working — `field` carries the substring offsets that paint and
  // scroll-to-match actually need.
  range: Range;
  start: number;
  end: number;
  text: string;
  /** Set when the match lies inside an <input> or <textarea> value. */
  field?: AdHocFieldDescriptor;
}

export interface AdHocSearchResult {
  matches: AdHocMatch[];
  count: number;
  // Filtered document text the offsets in `matches` refer to. Excludes
  // `<script>`/`<style>`/hidden subtrees — same string used for matching.
  // Snippet previews must slice this, not Element.textContent.
  text: string;
}

interface TextRun {
  kind: "text";
  node: Text;
  start: number;
  end: number;
}

interface FieldRun {
  kind: "field";
  element: HTMLInputElement | HTMLTextAreaElement;
  start: number;
  end: number;
}

type Run = TextRun | FieldRun;

const SKIP_TAGS = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE"]);
// Subtrees Highlighty owns and renders into the host page. Every one of
// these must be excluded from the search corpus, otherwise the bar
// counts hits inside its own UI:
//   - data-highlighty-cmdf   — the bar's shadow host
//   - data-highlighty-adhoc  — the paintAdHoc DOM fallback used when the
//                              CSS Custom Highlight API is unavailable
//   - data-highlighty-overlay — the form-field-highlighting overlay root
//                              (added in 2.4.6). Mirrors text from every
//                              eligible <textarea>/<input> with the source's
//                              value AND placeholder. A "Search stories by
//                              title, author..." input made the bar count
//                              one extra phantom "stories" match the user
//                              couldn't visually pinpoint because the
//                              mirror's text is rendered transparent.
const SKIP_ATTRS = [
  "data-highlighty-cmdf",
  "data-highlighty-adhoc",
  "data-highlighty-overlay",
];
const SHADOW_HOST_ID = "highlighty-cmdf-host";

export const isElementSkippable = (el: Element): boolean => {
  if (SKIP_TAGS.has(el.tagName)) return true;
  if (el.id === SHADOW_HOST_ID) return true;
  for (const attr of SKIP_ATTRS) if (el.hasAttribute(attr)) return true;
  const tag = el.tagName;
  // INPUT/TEXTAREA stay in the skippable set so other walkers that share
  // this filter (content.minimap context extraction, snippet ancestor
  // walks) don't pull field text into surrounding-context strings. The
  // cmd+F walker's acceptNode runs isFieldElement BEFORE this check, so
  // searchable INPUT/TEXTAREA still emit a FieldRun before being rejected.
  if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return true;
  if ((el as HTMLElement).isContentEditable) return true;
  // jsdom's isContentEditable getter is unreliable; fall back to the attribute.
  const ce = el.getAttribute("contenteditable");
  if (ce !== null && ce !== "false") return true;
  return false;
};

// CMF-43: only FREE-TEXT input types whose `.value` equals the rendered text
// are searched. Skipped: no-text-value types (hidden, password, button, submit,
// reset, checkbox, radio, file, image, color, range) AND the formatted types
// (number, date, datetime-local, month, week, time) — those index the canonical
// MACHINE value (`"2026-07-02"`, `"14:30"`), not what the control renders
// (locale `"07/02/2026"`, `"2:30 PM"`), so searching them found an invisible,
// un-locatable match that diverged from native Find. Restricting to the types
// whose `.value` IS the rendered text keeps the corpus visually honest.
const SEARCHABLE_INPUT_TYPES = new Set([
  "text",
  "search",
  "url",
  "email",
  "tel",
]);

export const isFieldElement = (
  el: Element,
): el is HTMLInputElement | HTMLTextAreaElement => {
  if (el.tagName === "TEXTAREA") return true;
  if (el.tagName !== "INPUT") return false;
  // `type` getter normalizes unknown/missing types to "text" — explicit
  // attribute read keeps jsdom + native behaviour aligned.
  const raw = (el as HTMLInputElement).type || el.getAttribute("type") || "text";
  return SEARCHABLE_INPUT_TYPES.has(raw.toLowerCase());
};

const readFieldText = (
  el: HTMLInputElement | HTMLTextAreaElement,
): string => {
  // .value is the live user-edited string; for unedited <textarea> it's
  // the defaultValue (which is also what the child text node reflects).
  // Either way `.value` is the right source of truth.
  const v = el.value;
  return typeof v === "string" ? v : "";
};

export const isElementInvisible = (el: Element): boolean => {
  // Single source of truth for "is this element worth matching inside?".
  // The TreeWalker rejects on this, which automatically excludes
  // descendants. Mirrors Chrome's native Find: skip display:none,
  // visibility:hidden, and content-visibility:auto/hidden — opacity:0
  // and aria-hidden are deliberately NOT filtered to match Chrome.
  //
  // Fast path: Element.checkVisibility() is purpose-built for this and
  // dramatically cheaper than getComputedStyle on a per-element basis —
  // critical on long pages (SEC filings: ~50k+ elements) where the walk
  // is the dominant cost of every search. Falls back to getComputedStyle
  // when the API isn't present (older engines, jsdom).
  const cv = (el as any).checkVisibility as
    | ((opts?: {
        contentVisibilityAuto?: boolean;
        visibilityProperty?: boolean;
      }) => boolean)
    | undefined;
  if (typeof cv === "function") {
    try {
      // CMF-37: contentVisibilityAuto is FALSE so `content-visibility: auto`
      // off-screen content is treated as VISIBLE-for-search. Native Chrome Find
      // matches inside cv:auto (it force-reveals/scrolls to it — the whole point
      // of pairing cv:auto with find-in-page), so excluding it (the old
      // `true`) UNDER-counted on exactly the large pages cv:auto targets.
      // Verified in real Chromium: checkVisibility still returns false for
      // content-visibility:HIDDEN and closed <details> regardless of this flag,
      // so VIS-02 (skip cv:hidden / closed-details) is preserved.
      const visible = cv.call(el, {
        contentVisibilityAuto: false,
        visibilityProperty: true,
      });
      if (visible) return false;
      // checkVisibility() returns false for `display: contents` because the
      // element itself generates no box — but its children render in the
      // parent's flow, which is the entire point of the property. Chakra UI,
      // MUI and emotion-styled layouts use contents-wrappers heavily; trusting
      // checkVisibility() blindly REJECTs the whole subtree from the
      // TreeWalker and the user sees 0/0 in the bar despite the text being
      // visibly on screen. Verify with getComputedStyle so we only treat
      // display:none / visibility:hidden / content-visibility:hidden as
      // genuinely invisible.
      let cs: CSSStyleDeclaration | null = null;
      if (typeof window !== "undefined" && window.getComputedStyle) {
        try {
          cs = window.getComputedStyle(el);
        } catch {
          cs = null;
        }
      }
      if (cs?.display === "contents") return false;
      return true;
    } catch {
      /* fall through to legacy path */
    }
  }
  if (typeof window === "undefined" || !window.getComputedStyle) return false;
  let cs: CSSStyleDeclaration | null = null;
  try {
    cs = window.getComputedStyle(el);
  } catch {
    return false;
  }
  if (!cs || !cs.display) return false;
  if (cs.display === "none") return true;
  if (cs.visibility === "hidden" || cs.visibility === "collapse") return true;
  return false;
};

// Collect runs from `root` AND every open shadow root / same-origin
// iframe reachable from it.
//
// The TreeWalker only descends the regular light-DOM tree. Open shadow
// roots are reached via element.shadowRoot, and iframe documents via
// iframe.contentDocument (same-origin only — cross-origin access throws
// or returns null, which we silently skip).
//
// Discovery happens as a side-effect of acceptNode (we push shadow hosts
// + iframe elements onto pending queues), then a drain loop walks each.
// Visited sets prevent cycles in pathological web-component setups.
//
// Returns the additional roots we walked alongside `runs`/`text` so
// the cached finder can install MutationObservers on each, ensuring
// mutations inside shadow / iframe content invalidate the cache.
export const collectRuns = (
  root: Node = document.body
): {
  text: string;
  runs: Run[];
  shadowRoots: ShadowRoot[];
  frameDocs: Document[];
  blockSeparatorOffsets: number[];
} => {
  let text = "";
  // CMF-28: the raw offsets at which appendTextRun inserted a BLOCK-boundary
  // `\n`. Normalization (`normalizeSearchTextWithMap`) collapses every `\s`
  // run — including these separators — into a single space, so a plain-mode
  // PHRASE query with an internal space would otherwise match straight across
  // a block boundary the `\n` was meant to seal (re-opening CMF-02 for
  // multi-word queries). findPlainMatches rejects any match whose raw span
  // crosses one of these offsets. Kept separate from CONTENT newlines (a
  // literal `\n` inside `<pre>` node.data is NOT a barrier) and from the regex
  // path (its `^`/`$`/`\s` semantics on the raw `\n` are intentional). Always
  // ascending (text grows monotonically), so a binary search suffices.
  const blockSeparatorOffsets: number[] = [];
  // Track whether the corpus currently ends with a "\n" WITHOUT reading `text`.
  // `text` is built lazily by `+=` (a cons-string); calling `text.endsWith("\n")`
  // forces V8 to FLATTEN the whole rope every time → O(n) per call → O(n²) over
  // tens of thousands of text nodes (a SEC-filing's cells). A tracked flag keeps
  // the separator check O(1).
  let endsWithNewline = false;
  const runs: Run[] = [];
  const shadowRoots: ShadowRoot[] = [];
  const frameDocs: Document[] = [];
  const seenShadowRoots = new Set<ShadowRoot>();
  const seenDocs = new Set<Document>();

  const pendingShadowHosts: Element[] = [];
  const pendingFrames: HTMLIFrameElement[] = [];

  const appendFieldRun = (el: HTMLInputElement | HTMLTextAreaElement) => {
    const value = readFieldText(el);
    if (!value) return;
    // Separator before and after the field's value so a stray plain or
    // regex match can't cross from page text into a field's value (the
    // bar would build a Range it has no way to paint). A literal newline
    // breaks word boundaries cleanly for plain/fuzzy modes and is what
    // findRunForOffset's binary search expects between runs anyway.
    if (text.length && !endsWithNewline) text += "\n";
    const start = text.length;
    text += value;
    runs.push({ kind: "field", element: el, start, end: text.length });
    text += "\n";
    endsWithNewline = true;
  };

  // CMF-02: the finder corpus must break at BLOCK-level boundaries so a match
  // can't straddle two visual blocks (`<td>12</td><td>34</td>` + "1234" → 0, not
  // a phantom 1), mirroring Chrome native Find and `appendFieldRun`'s field
  // separators. We emit a `\n` into the corpus when a text node's nearest
  // block-level ancestor differs from the previous run's. Inline-level elements
  // (and `display:contents`, which generates no box) are transparent, so text
  // split only by inline markup (`a<b>b</b>c` → "abc") still joins into one run.
  // The `m`-flagged regex `^`/`$` then line-anchor as advertised in the tooltip.
  // Boundary detection is TAG-FIRST: HTML elements whose default display is
  // block-level (below) are boundaries via a fast Set lookup. `getComputedStyle`
  // is deliberately NOT consulted for block tags — on a cell-dense page (a SEC
  // filing: one text node per `<td>`) that would fire tens of thousands of times
  // (a ~3.5x regression), and `checkVisibility` already avoids per-element style
  // in the visibility pass. CMF-29 adds a computed-`display` check ONLY for
  // NON-block-tag (inline) elements (see `isCssBlockBoundary`), so a block-tag
  // text node never pays it — the cell-dense fast path is preserved — while a
  // CSS-forced-block inline tag (Tailwind `.block`, flex/grid column) or a
  // `<summary>` now correctly separates. The PDF text-layer runs
  // (`position:absolute <span>`s) are kept continuous by the absolute/fixed
  // carve-out in `isCssBlockBoundary`, not by an inline-tag blanket rule.
  const BLOCK_LEVEL_TAGS = new Set([
    "ADDRESS", "ARTICLE", "ASIDE", "BLOCKQUOTE", "DETAILS", "DIALOG", "DD",
    "DIV", "DL", "DT", "FIELDSET", "FIGCAPTION", "FIGURE", "FOOTER", "FORM",
    "H1", "H2", "H3", "H4", "H5", "H6", "HEADER", "HGROUP", "HR", "LI", "MAIN",
    "NAV", "OL", "P", "PRE", "SECTION", "TABLE", "TBODY", "TD", "TFOOT", "TH",
    "THEAD", "TR", "UL", "CAPTION", "BODY", "HTML", "BR",
    // CMF-29: SUMMARY is block-level by default (`display: list-item`) but was
    // omitted — a `<summary>` label joined the following text into a phantom.
    "SUMMARY",
  ]);
  // CMF-29: computed `display` values that start a new visual block/line, kept
  // as a Set for the per-element check below.
  const BLOCK_DISPLAYS = new Set([
    "block", "flex", "grid", "list-item", "flow-root", "table",
    "table-row", "table-row-group", "table-header-group",
    "table-footer-group", "table-caption",
    // CMF-45: a CSS-forced `display:table-cell`/`table-column` inline element
    // lays out like adjacent `<td>`s (which CMF-02 established must not
    // phantom-join).
    "table-cell", "table-column", "table-column-group",
    // CMF-48: atomic INLINE-level boxes (inline-block/flex/grid/table + the
    // -webkit-box variants) establish an independent formatting context, and
    // native Find SEPARATES text across two adjacent such boxes (verified via
    // window.find() on zero-whitespace siblings) — so they ARE boundaries. The
    // earlier "they flow inline, deliberately absent" reasoning was a false
    // negative from a whitespace-separated test fixture (the whitespace made the
    // corpus join WITH a space, masking the no-whitespace phantom-join). The
    // out-of-flow carve-out in isCssBlockBoundary still keeps the PDF text layer
    // (position:absolute spans) joined.
    "inline-block", "inline-flex", "inline-grid", "inline-table",
    "-webkit-box", "-webkit-inline-box",
  ]);
  // CMF-29: the tag-only model is right for the common case but blind to CSS
  // that forces an INLINE tag to block/flex/grid (Tailwind `class="block"`,
  // flex/grid columns) — those phantom-join across visual lines (the mirror of
  // CMF-02 for CSS overrides). We consult computed style, but ONLY for
  // non-block-tag elements (below), so the ~3.5x cell-dense regression the
  // tag-only model avoided doesn't return: a `<td>`/`<p>` text node stops at
  // the fast tag check and never calls getComputedStyle. Cached per element.
  //
  // PDF carve-out (no id/class coupling needed): the PDF text-layer runs are
  // `position:absolute <span>`s, which the engine BLOCKIFIES to computed
  // `display:block` — but they must stay one continuous corpus. We therefore
  // treat only IN-FLOW (static/relative) block-ish display as a boundary;
  // out-of-flow (absolute/fixed) inline elements stay transparent, keeping the
  // PDF text layer joined and not separating positioned badges/tooltips.
  const cssBoundaryCache = new Map<Element, boolean>();
  const isCssBlockBoundary = (el: Element): boolean => {
    const cached = cssBoundaryCache.get(el);
    if (cached !== undefined) return cached;
    let result = false;
    try {
      const win = el.ownerDocument?.defaultView;
      if (win) {
        const cs = win.getComputedStyle(el);
        const pos = cs.position;
        if (pos !== "absolute" && pos !== "fixed") {
          result = BLOCK_DISPLAYS.has(cs.display);
        }
      }
    } catch {
      /* detached / cross-origin / no view — treat as inline (no boundary) */
    }
    cssBoundaryCache.set(el, result);
    return result;
  };
  // A BLOCK tag is a boundary (fast path). An inline tag is a boundary only
  // when computed style makes it block-level and in-flow (CMF-29). The `||`
  // short-circuits so getComputedStyle fires ONLY for non-block-tag elements.
  const isBlockBoundaryElement = (el: Element): boolean =>
    BLOCK_LEVEL_TAGS.has(el.tagName) || isCssBlockBoundary(el);
  const blockAncestorByParent = new Map<Element, Element | null>();
  const getBlockBoundaryAncestor = (node: Text): Element | null => {
    const parent = node.parentElement;
    if (!parent) return null;
    const cached = blockAncestorByParent.get(parent);
    if (cached !== undefined) return cached;
    let el: Element | null = parent;
    while (el && !isBlockBoundaryElement(el)) {
      el = el.parentElement;
    }
    blockAncestorByParent.set(parent, el);
    return el;
  };
  let previousBlockAncestor: Element | null | undefined = undefined;

  const appendTextRun = (node: Text) => {
    const block = getBlockBoundaryAncestor(node);
    const isBlockTransition =
      previousBlockAncestor !== undefined &&
      block !== previousBlockAncestor &&
      text.length > 0;
    if (isBlockTransition) {
      if (!endsWithNewline) {
        // Emit a fresh separator and record its offset.
        blockSeparatorOffsets.push(text.length); // CMF-28: offset of the block `\n`
        text += "\n";
        endsWithNewline = true;
      } else {
        // CMF-28 (Defect 1): the corpus ALREADY ends with a `\n` — either a
        // prior separator OR (dominant real case) the previous text node's own
        // data ended in a newline, which is ubiquitous in pretty-printed HTML
        // (`<p>\n  text\n</p>`) and MediaWiki/Wikipedia output. We correctly
        // suppress a double `\n`, but the block barrier still exists at that
        // trailing newline (offset text.length - 1) and MUST be recorded, or a
        // plain phrase phantom-crosses it (the very bug CMF-28 fixes). Dedupe
        // against the last offset to keep the array strictly ascending.
        const sepOffset = text.length - 1;
        if (
          blockSeparatorOffsets[blockSeparatorOffsets.length - 1] !== sepOffset
        ) {
          blockSeparatorOffsets.push(sepOffset);
        }
      }
    }
    previousBlockAncestor = block;
    const start = text.length;
    text += node.data;
    // node.data is a single Text node's content (short) — endsWith on it is O(1)
    // in practice, never a flatten of the growing corpus.
    if (node.data.length) endsWithNewline = node.data.endsWith("\n");
    runs.push({ kind: "text", node, start, end: text.length });
  };

  const walkSubtree = (startNode: Node) => {
    const ownerDoc =
      startNode.nodeType === Node.DOCUMENT_NODE
        ? (startNode as Document)
        : startNode.ownerDocument ?? document;
    const walker = ownerDoc.createTreeWalker(
      startNode,
      NodeFilter.SHOW_ELEMENT | NodeFilter.SHOW_TEXT,
      {
        acceptNode: (n: Node) => {
          if (n.nodeType === Node.ELEMENT_NODE) {
            const el = n as Element;
            // Visibility check fires BEFORE the field check: invisible
            // inputs (display:none search rows, hidden offscreen forms)
            // mirror Chrome's native Find behaviour and shouldn't count.
            if (isElementInvisible(el)) return NodeFilter.FILTER_REJECT;
            if (isFieldElement(el)) {
              appendFieldRun(el as HTMLInputElement | HTMLTextAreaElement);
              return NodeFilter.FILTER_REJECT;
            }
            // CMF-42: native Find matches text inside contenteditable regions
            // (Gmail/Slack/Notion editors). Search NON-focused ones, but skip the
            // surface the user is ACTIVELY EDITING so we don't paint a highlight
            // under their cursor (the original rationale, narrowed from "skip all
            // contenteditable"). Handled HERE, before the shared isElementSkippable
            // (which still skips ALL contenteditable for the OTHER walkers that
            // share it — content.minimap / snippet context walks). Painting is via
            // the CSS Custom Highlight API (no DOM mutation), so it's safe inside
            // an editor's own reconciled DOM. FILTER_SKIP (not REJECT) for a
            // non-focused editable so the walker still visits its text nodes.
            const ceAttr = el.getAttribute("contenteditable");
            const isEditable =
              (el as HTMLElement).isContentEditable ||
              (ceAttr !== null && ceAttr !== "false");
            if (isEditable) {
              // CMF-51: resolve the SHADOW-LOCAL active element via getRootNode().
              // For a contenteditable inside an open shadow root the DOM retargets
              // document.activeElement to the shadow HOST, so
              // ownerDocument.activeElement would miss the focused inner editor and
              // wrongly search the surface the user is editing. A ShadowRoot (like
              // Document) exposes its own tree-local activeElement.
              const root = el.getRootNode();
              const active =
                root instanceof Document || root instanceof ShadowRoot
                  ? root.activeElement
                  : null;
              const isFocusedEditingSurface =
                !!active && (el === active || el.contains(active));
              return isFocusedEditingSurface
                ? NodeFilter.FILTER_REJECT
                : NodeFilter.FILTER_SKIP;
            }
            if (isElementSkippable(el)) return NodeFilter.FILTER_REJECT;
            // Iframe: schedule contentDocument descent (same-origin only;
            // contentDocument throws or returns null for cross-origin).
            if (el.tagName === "IFRAME") {
              pendingFrames.push(el as HTMLIFrameElement);
              return NodeFilter.FILTER_REJECT;
            }
            // Open shadow root: schedule recursion into it. The walker
            // can't enter shadow DOM on its own, so we drain shadow hosts
            // after this walker finishes.
            const sr = (el as HTMLElement).shadowRoot;
            if (sr && !seenShadowRoots.has(sr)) {
              pendingShadowHosts.push(el);
            }
            return NodeFilter.FILTER_SKIP;
          }
          const value = (n as Text).data;
          if (!value || !value.length) return NodeFilter.FILTER_REJECT;
          return NodeFilter.FILTER_ACCEPT;
        },
      }
    );
    let current: Node | null = walker.nextNode();
    while (current) {
      appendTextRun(current as Text);
      current = walker.nextNode();
    }
  };

  const walkShadowRoot = (sr: ShadowRoot) => {
    if (seenShadowRoots.has(sr)) return;
    seenShadowRoots.add(sr);
    shadowRoots.push(sr);
    // TreeWalker accepts a ShadowRoot as its root.
    walkSubtree(sr as unknown as Node);
  };

  const walkFrameDoc = (doc: Document) => {
    if (seenDocs.has(doc)) return;
    seenDocs.add(doc);
    frameDocs.push(doc);
    const body = doc.body;
    if (body) walkSubtree(body);
  };

  // Initial walk.
  walkSubtree(root);

  // Drain shadow hosts and iframes. Each can produce more (a shadow root
  // may contain another shadow host or another iframe).
  while (pendingShadowHosts.length || pendingFrames.length) {
    while (pendingShadowHosts.length) {
      const host = pendingShadowHosts.shift()!;
      const sr = (host as HTMLElement).shadowRoot;
      if (!sr) continue;
      walkShadowRoot(sr);
    }
    while (pendingFrames.length) {
      const frame = pendingFrames.shift()!;
      let doc: Document | null = null;
      try {
        doc = frame.contentDocument;
      } catch {
        // Cross-origin → contentDocument access throws. Silent skip.
        continue;
      }
      if (!doc) continue;
      walkFrameDoc(doc);
    }
  }

  return { text, runs, shadowRoots, frameDocs, blockSeparatorOffsets };
};

// CMF-28: does the half-open raw span [start, end) contain a block-separator
// offset? `offsets` is ascending, so binary-search the first offset >= start
// and check it falls before `end`. Used to reject plain-mode phrase matches
// that would straddle a block boundary once normalization collapsed the `\n`.
const spansBlockSeparator = (
  offsets: number[],
  start: number,
  end: number
): boolean => {
  if (offsets.length === 0 || end - start <= 0) return false;
  let lo = 0;
  let hi = offsets.length; // first index with offsets[i] >= start
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (offsets[mid] < start) lo = mid + 1;
    else hi = mid;
  }
  return lo < offsets.length && offsets[lo] < end;
};

const findRunForOffset = (runs: Run[], offset: number): { run: Run; local: number } | null => {
  // Binary search: runs are non-overlapping and ordered by `start`.
  let lo = 0;
  let hi = runs.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const run = runs[mid];
    if (offset < run.start) hi = mid - 1;
    else if (offset >= run.end) lo = mid + 1;
    else return { run, local: offset - run.start };
  }
  return null;
};

// QRX-14: runs are separated in `text` by synthetic `\n` characters (inserted
// around field values) that belong to no run. A regex/fuzzy span whose START
// lands on such a separator would make findRunForOffset(start) return null and
// the whole match get dropped. Clamp the start FORWARD to the first character
// of the nearest enclosing real run at or after `from` (bounded by `limit`, the
// match's exclusive end), so the paintable portion of the match survives.
const clampStartIntoRun = (
  runs: Run[],
  from: number,
  limit: number,
): { run: Run; local: number; offset: number } | null => {
  // runs are ordered by `start`; scan forward for the first run that begins at
  // or after `from` and starts strictly before the match end.
  for (const run of runs) {
    if (run.end <= from) continue;
    const offset = Math.max(from, run.start);
    if (offset >= limit) return null;
    if (offset >= run.start && offset < run.end) {
      return { run, local: offset - run.start, offset };
    }
  }
  return null;
};

// QRX-14 (mirror of clampStartIntoRun for the END endpoint): clamp the last
// consumed character BACKWARD to the nearest enclosing real run at or before
// `from`, bounded below by `floor` (the clamped start) so we never produce an
// inverted span.
const clampLastCharIntoRun = (
  runs: Run[],
  from: number,
  floor: number,
): { run: Run; local: number; offset: number } | null => {
  for (let i = runs.length - 1; i >= 0; i--) {
    const run = runs[i];
    if (run.start > from) continue;
    const offset = Math.min(from, run.end - 1);
    if (offset < floor) return null;
    if (offset >= run.start && offset < run.end) {
      return { run, local: offset - run.start, offset };
    }
  }
  return null;
};

interface MatchTarget {
  range: Range;
  field?: AdHocFieldDescriptor;
}

const buildMatchTarget = (
  runs: Run[],
  start: number,
  end: number,
): MatchTarget | null => {
  let startInfo = findRunForOffset(runs, start);
  // end is exclusive — locate the last consumed character (end - 1) then offset by 1
  let lastCharInfo = findRunForOffset(runs, Math.max(start, end - 1));

  // QRX-14: an endpoint can land on a between-run `\n` separator (which belongs
  // to no run). Rather than drop the entire match — which under-reports the
  // count and makes Enter-cycling skip it — clamp the offending endpoint to the
  // nearest enclosing real run. The match's paintable span shrinks to the run
  // boundary instead of vanishing.
  if (!startInfo) {
    const clamped = clampStartIntoRun(runs, start, Math.max(start + 1, end));
    if (!clamped) return null;
    startInfo = { run: clamped.run, local: clamped.local };
    start = clamped.offset;
  }
  if (!lastCharInfo) {
    const clamped = clampLastCharIntoRun(runs, Math.max(start, end - 1), start);
    if (!clamped) return null;
    lastCharInfo = { run: clamped.run, local: clamped.local };
  }

  const startRun = startInfo.run;
  const endRun = lastCharInfo.run;

  // Field-internal match: both endpoints land in the same FieldRun. Build
  // a synthetic Range that wraps the field element so consumers that
  // expect a Range (scrollbar bucket rects, snippet ancestor lookups)
  // still work; carry the substring offsets in `field` for paint/scroll.
  if (startRun.kind === "field") {
    if (endRun !== startRun) return null;
    const range = document.createRange();
    try {
      range.selectNode(startRun.element);
    } catch {
      return null;
    }
    return {
      range,
      field: {
        element: startRun.element,
        fieldStart: startInfo.local,
        fieldEnd: lastCharInfo.local + 1,
      },
    };
  }

  // Mixed (text → field or field → text) match → reject. The separator
  // newlines around field runs make this rare in plain/fuzzy mode; greedy
  // regex matchers could still reach across, and there's no sensible way
  // to paint or scroll such a match.
  if (endRun.kind === "field") return null;

  const range = document.createRange();
  range.setStart(startRun.node, startInfo.local);
  range.setEnd(endRun.node, lastCharInfo.local + 1);
  return { range };
};

const findPlainMatches = (
  text: string,
  runs: Run[],
  term: string,
  modifiers: AdHocSearchModifiers,
  // CMF-28: raw offsets of BLOCK-boundary separators. A plain phrase whose
  // span crosses one is a cross-block phantom (normalization collapsed the
  // `\n` to a matchable space) and is rejected. Defaults to none so callers
  // that don't have them (older/simple callers) keep prior behavior.
  blockSeparatorOffsets: number[] = []
): AdHocMatch[] => {
  const opts = {
    caseSensitive: modifiers.caseSensitive,
    diacriticSensitive: modifiers.diacriticSensitive,
  };
  const normTerm = normalizeSearchTextWithMap(term, opts);
  if (!normTerm.value.length) return [];
  const normDoc = normalizeSearchTextWithMap(text, opts);

  const results: AdHocMatch[] = [];
  let cursor = 0;
  while (cursor < normDoc.value.length) {
    const idx = normDoc.value.indexOf(normTerm.value, cursor);
    if (idx === -1) break;
    const endIdx = idx + normTerm.value.length;

    const passesBoundary =
      !modifiers.wholeWord ||
      (isWordBoundary(normDoc.value, idx - 1) &&
        isWordBoundary(normDoc.value, endIdx));

    if (passesBoundary) {
      const origStart = normDoc.sourceMap[idx] ?? idx;
      const origEnd = (normDoc.sourceMap[endIdx - 1] ?? origStart) + 1;
      // CMF-28: reject a phrase that straddles a block boundary. The `\n`
      // separator was collapsed to a space in normDoc, so indexOf happily
      // matched "world foo" across `<p>world</p><p>foo</p>`; the raw span then
      // spans the separator offset. (Regex keeps raw `^`/`$`/`\s` semantics;
      // fuzzy is word-segmented — only plain phrases can cross.)
      if (spansBlockSeparator(blockSeparatorOffsets, origStart, origEnd)) {
        // CMF-28 (Defect 2): advance by ONE, not the full term length — a
        // real in-block match can overlap the rejected cross-block candidate
        // (`<p>a</p><p>a a</p>` + "a a": the cross-block hit at idx 0 is
        // rejected, but the genuine in-block "a a" starts one char later).
        // Skipping the whole term would turn a phantom into a miss.
        cursor = idx + 1;
        continue;
      }
      const target = buildMatchTarget(runs, origStart, origEnd);
      if (target) {
        results.push({
          range: target.range,
          start: origStart,
          end: origEnd,
          text: text.slice(origStart, origEnd),
          ...(target.field ? { field: target.field } : {}),
        });
      }
    }

    cursor = idx + Math.max(normTerm.value.length, 1);
  }
  return results;
};

const findRegexMatches = (
  text: string,
  runs: Run[],
  term: string,
  modifiers: AdHocSearchModifiers
): AdHocMatch[] => {
  // QRX-04: a catastrophically-backtracking pattern (e.g. (a+)+b) would hang the
  // content script's main thread — JS can't interrupt a running RegExp.exec.
  // Reject known-dangerous shapes before compiling (the same static guard the
  // saved-highlight engine uses), so the Cmd+F bar stays responsive. This is a
  // content script on arbitrary pages where a Worker may be blocked by page CSP,
  // so the synchronous guard — not the PDF engine's worker — is the right fit.
  if (isLikelyCatastrophic(term)) {
    if (!warnedCatastrophicCmdFPatterns.has(term)) {
      warnedCatastrophicCmdFPatterns.add(term);
      // eslint-disable-next-line no-console
      console.warn(
        `[highlighty] Cmd+F regex "${term}" was skipped — pattern matches a known catastrophic-backtrack shape and would hang the page.`
      );
    }
    return [];
  }

  // QRX-16: honor whole-word by WRAPPING the user pattern in zero-width
  // word-boundary lookarounds (shared `wrapRegexWholeWord`) rather than a
  // post-match boundary filter. Baking the boundary into the pattern lets
  // alternation backtrack to a longer whole-word alternative the post-filter
  // dropped (`cat|category` on "category" → "category", not 0), so the Cmd+F
  // surface agrees with the on-page mark.js highlighter (QRX-06). The
  // catastrophic-backtrack guard above runs on the RAW `term`, so the
  // zero-width, non-capturing wrap never hides a dangerous shape from it.
  const flags = `gm${modifiers.caseSensitive ? "" : "i"}u`;
  let regex: RegExp;
  try {
    // QRX-20: validate the raw term before whole-word-wrapping (see
    // compileWholeWordRegex) so a malformed class can't become a valid-but-wrong
    // regex when wholeWord is on.
    regex = compileWholeWordRegex(term, flags, modifiers.wholeWord);
  } catch {
    return [];
  }
  const results: AdHocMatch[] = [];
  let m: RegExpExecArray | null;
  while ((m = regex.exec(text))) {
    const start = m.index;
    const end = m.index + m[0].length;
    if (m[0].length === 0) {
      // QRX-07: advance past the whole code point (flags include `u`; a flat
      // += 1 splits a surrogate pair before an astral char and freezes this
      // content thread). Shared helper with src/search/regexExec.ts.
      regex.lastIndex = advanceRegexIndex(text, regex.lastIndex);
      continue;
    }
    // QRX-03/QRX-16: whole-word for regex is enforced INSIDE the compiled
    // pattern above (zero-width lookarounds), so no post-match boundary filter
    // is needed here — and the pattern-level constraint correctly lets
    // alternation fall through to a longer whole-word alternative.
    const target = buildMatchTarget(runs, start, end);
    if (target) {
      results.push({
        range: target.range,
        start,
        end,
        text: m[0],
        ...(target.field ? { field: target.field } : {}),
      });
    }
  }
  return results;
};

const levenshteinBounded = (a: string, b: string, maxDistance: number): number => {
  // Standard DP, exits early when the row's minimum exceeds maxDistance.
  // Returns Infinity when the bound is exceeded so callers can reject.
  if (Math.abs(a.length - b.length) > maxDistance) return Infinity;
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = new Array(n + 1);
  let curr = new Array(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    let rowMin = curr[0];
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(curr[j - 1] + 1, prev[j] + 1, prev[j - 1] + cost);
      if (curr[j] < rowMin) rowMin = curr[j];
    }
    if (rowMin > maxDistance) return Infinity;
    [prev, curr] = [curr, prev];
  }
  return prev[n] <= maxDistance ? prev[n] : Infinity;
};

const findFuzzyMatches = (
  text: string,
  runs: Run[],
  term: string,
  modifiers: AdHocSearchModifiers,
  blockSeparatorOffsets: number[] = []
): AdHocMatch[] => {
  if (term.length < 3)
    return findPlainMatches(text, runs, term, modifiers, blockSeparatorOffsets);
  const opts = {
    caseSensitive: modifiers.caseSensitive,
    diacriticSensitive: modifiers.diacriticSensitive,
  };
  const normTerm = normalizeSearchTextWithMap(term, opts).value;
  if (!normTerm.length) return [];
  const normDoc = normalizeSearchTextWithMap(text, opts);
  const threshold = Math.max(1, Math.floor(normTerm.length / 4));

  const results: AdHocMatch[] = [];
  // Word-segmented fuzzy: walk word boundaries, test each word for
  // bounded edit distance to the term. Cheaper than sliding-window over
  // every offset; acceptable for typical page sizes.
  const wordRegex = /[\p{L}\p{N}_]+/gu;
  let match: RegExpExecArray | null;
  while ((match = wordRegex.exec(normDoc.value))) {
    const word = match[0];
    if (Math.abs(word.length - normTerm.length) > threshold) continue;
    const dist = levenshteinBounded(word, normTerm, threshold);
    if (dist <= threshold) {
      const startNorm = match.index;
      const endNorm = match.index + word.length;
      const origStart = normDoc.sourceMap[startNorm] ?? startNorm;
      const origEnd = (normDoc.sourceMap[endNorm - 1] ?? origStart) + 1;
      const target = buildMatchTarget(runs, origStart, origEnd);
      if (target) {
        results.push({
          range: target.range,
          start: origStart,
          end: origEnd,
          text: text.slice(origStart, origEnd),
          ...(target.field ? { field: target.field } : {}),
        });
      }
    }
  }
  return results;
};

export const find = (
  term: string,
  modifiers: AdHocSearchModifiers,
  root: Node = document.body
): AdHocSearchResult => {
  if (!term || !term.length) return { matches: [], count: 0, text: "" };
  const collected = collectRuns(root);
  const { text, runs, blockSeparatorOffsets } = collected;
  if (!text.length) return { matches: [], count: 0, text };

  let matches: AdHocMatch[];
  if (modifiers.regex) matches = findRegexMatches(text, runs, term, modifiers);
  else if (modifiers.fuzzy)
    matches = findFuzzyMatches(text, runs, term, modifiers, blockSeparatorOffsets);
  else matches = findPlainMatches(text, runs, term, modifiers, blockSeparatorOffsets);

  return { matches, count: matches.length, text };
};

/**
 * Same as find() but restricts results to ranges that fall *inside* an
 * existing saved-highlight DOM element (any element with a
 * data-hility attribute, our existing saved-highlight tag). Useful for
 * "search inside what I've already highlighted" — narrowing a broad
 * highlight to specific terms within it.
 */
// CMF-36: the "search inside saved highlights" restriction is a pure post-
// filter over a full search result — extracted so a CACHED finder's result can
// be filtered too. The bar (BarRoot) runs the cached finder (which installs the
// MutationObserver that drives the count-refresh on DOM changes) and applies
// this filter, so H-mode counts refresh after the page settles just like the
// unfiltered mode. `findInsideSavedHighlights` (used by the cross-tab probe,
// where no observer is needed) is now this filter over the uncached `find`.
export const filterMatchesToSavedHighlights = (
  result: AdHocSearchResult
): AdHocSearchResult => {
  if (!result.matches.length) return result;
  const filtered = result.matches.filter((m) => {
    // CMF-50: a FIELD match (<input>/<textarea> value) is never inside a
    // [data-hility] saved highlight — field values are highlighted via the
    // overlay mirror, not wrapped in <hility>. Its synthetic range wraps the
    // field via selectNode, so startContainer is the field's PARENT, which is a
    // ShadowRoot (a DocumentFragment, NO `.closest`) when the field is a direct
    // shadow-root child. The old blind `start as Element` cast then threw
    // `node.closest is not a function`, and under CMF-36's corpusTick effect
    // that TypeError unmounted the whole bar. Exclude field matches up front.
    if (m.field) return false;
    const start = m.range.startContainer;
    // Defense-in-depth: resolve to an Element with `.closest` only for Text /
    // Element start containers; anything else (a bare DocumentFragment, etc.)
    // isn't inside a saved highlight and must not crash the filter.
    const node =
      start.nodeType === Node.TEXT_NODE
        ? (start.parentElement as Element | null)
        : start.nodeType === Node.ELEMENT_NODE
        ? (start as Element)
        : null;
    if (!node) return false;
    return Boolean(node.closest("[data-hility]"));
  });
  return { matches: filtered, count: filtered.length, text: result.text };
};

export const findInsideSavedHighlights = (
  term: string,
  modifiers: AdHocSearchModifiers,
  root: Node = document.body
): AdHocSearchResult =>
  filterMatchesToSavedHighlights(find(term, modifiers, root));

// On large pages (SEC filings, long product catalogs) collectRuns is the
// dominant cost — TreeWalker + getComputedStyle per element runs at
// O(elements) and dwarfs the matcher itself. With the bar's per-keystroke
// debounce calling find() once per search, every keystroke pays that DOM
// walk. createCachedFinder caches the (text, runs) tuple for a given
// root, invalidating on a debounced MutationObserver so layout-changing
// edits (toggled accordions, async-loaded content) rebuild on demand.
// Typing the same term twice, or hitting different queries against
// unchanged content, becomes O(matcher-only).
export interface CachedFinderOptions {
  /** MutationObserver debounce before invalidating the cache. */
  mutationDebounceMs?: number;
  /**
   * CMF-49: max-wait cap for the debounce. Under a sustained mutation storm
   * (style/class writes from animation libs, progress bars, spinners) the
   * trailing debounce would reset forever and never invalidate; this forces an
   * invalidate after this much CONTINUOUS deferred activity. Defaults to
   * max(1500, debounce × 3).
   */
  mutationMaxWaitMs?: number;
  /**
   * Fires when the cached corpus is invalidated (DOM mutation debounce
   * elapsed, or a form-field value changed). Bars subscribe so they can
   * re-run their last search — otherwise the count would lag behind page
   * edits until the user touches the bar again.
   */
  onInvalidate?: () => void;
}

export interface CachedFinder {
  find: typeof find;
  /** Force the next find() to rebuild the (text, runs) cache. */
  invalidate: () => void;
  /** Tear down the MutationObserver. Call on unmount. */
  dispose: () => void;
}

export const createCachedFinder = (
  opts: CachedFinderOptions = {}
): CachedFinder => {
  const debounceMs = opts.mutationDebounceMs ?? 500;
  // CMF-49: cap on how long the trailing debounce may keep deferring under a
  // continuous storm before we force an invalidate.
  const maxWaitMs = opts.mutationMaxWaitMs ?? Math.max(1500, debounceMs * 3);
  const onInvalidate = opts.onInvalidate;
  let cache:
    | { root: Node; text: string; runs: Run[]; blockSeparatorOffsets: number[] }
    | null = null;
  const observers = new Map<Node, MutationObserver>();
  const frameDocsObserved = new Set<Document>();
  let invalidateTimer: ReturnType<typeof setTimeout> | null = null;
  // CMF-49: armed once when a debounce window opens, NEVER reset by subsequent
  // events — so a sustained storm can't starve the invalidate.
  let maxWaitTimer: ReturnType<typeof setTimeout> | null = null;
  let inputListenerAttached = false;

  const notify = () => {
    try {
      onInvalidate?.();
    } catch {
      /* swallow — invalidation must not throw to MutationObserver */
    }
  };

  const invalidate = () => {
    const wasFresh = cache !== null;
    cache = null;
    if (wasFresh) notify();
  };

  const onFieldInput = (ev: Event) => {
    // Form-field value changes don't fire DOM mutations, so the
    // MutationObserver above misses them. Without this listener, the bar
    // would happily search a corpus built from stale .value reads after
    // the user types in a page input (TSH Chat /guest/stories repro).
    // Fire immediately — input events are user-paced, not storm-prone.
    const target = ev.target as Element | null;
    if (!target) return;
    const tag = target.tagName;
    if (tag !== "INPUT" && tag !== "TEXTAREA") return;
    if (target.closest("[data-highlighty-cmdf], [data-highlighty-overlay]")) {
      // Our own bar input or a form-field overlay mirror — not page content.
      return;
    }
    invalidate();
  };

  // CMF-49: fire (and clear BOTH timers) — used by the trailing debounce and by
  // the max-wait cap, so whichever wins resets the whole window cleanly.
  const fireInvalidate = () => {
    if (invalidateTimer) {
      clearTimeout(invalidateTimer);
      invalidateTimer = null;
    }
    if (maxWaitTimer) {
      clearTimeout(maxWaitTimer);
      maxWaitTimer = null;
    }
    invalidate();
  };

  const scheduleInvalidate = () => {
    // Trailing debounce: coalesces a normal burst (reset on each event).
    if (invalidateTimer) clearTimeout(invalidateTimer);
    invalidateTimer = setTimeout(fireInvalidate, debounceMs);
    // CMF-49: max-wait — armed ONCE per window and never reset, so a sustained
    // storm (style/class writes that keep re-arming the trailing timer) can't
    // starve the invalidate forever. Whichever timer fires first calls
    // fireInvalidate, which clears both and starts a fresh window next event.
    if (!maxWaitTimer) maxWaitTimer = setTimeout(fireInvalidate, maxWaitMs);
  };

  const teardownObservers = () => {
    observers.forEach((o) => o.disconnect());
    observers.clear();
    // IFR-02: remove the per-iframe input listeners attached in observeAll
    // (before clearing the set we iterate to find them).
    frameDocsObserved.forEach((doc) => {
      try {
        doc.removeEventListener("input", onFieldInput, true);
      } catch {
        /* detached / cross-origin — ignore */
      }
    });
    frameDocsObserved.clear();
    if (invalidateTimer) {
      clearTimeout(invalidateTimer);
      invalidateTimer = null;
    }
    // CMF-49: tear down the max-wait timer too (else a pending storm cap could
    // fire an invalidate after dispose).
    if (maxWaitTimer) {
      clearTimeout(maxWaitTimer);
      maxWaitTimer = null;
    }
    if (inputListenerAttached && typeof document !== "undefined") {
      document.removeEventListener("input", onFieldInput, true);
      // CMF-38: paired with the scroll listener attached in observeAll.
      document.removeEventListener("scroll", scheduleInvalidate, {
        capture: true,
      } as any);
      inputListenerAttached = false;
    }
  };

  // Observe one node (light-DOM root, ShadowRoot, or iframe Document).
  // Idempotent — re-observing the same node is a no-op so a re-walk after
  // cache invalidation doesn't churn observers.
  const observeNode = (target: Node) => {
    if (observers.has(target)) return;
    if (typeof MutationObserver === "undefined") return;
    const ctor =
      (target.ownerDocument?.defaultView as unknown as {
        MutationObserver?: typeof MutationObserver;
      } | null)?.MutationObserver ?? MutationObserver;
    const observer = new ctor(() => {
      // Debounce: layout-thrash storms (e.g. virtualized lists scrolling)
      // would otherwise rebuild text/runs on every micro-mutation.
      scheduleInvalidate();
    });
    observer.observe(target, {
      subtree: true,
      childList: true,
      characterData: true,
      // CMF-38: also watch the attributes that flip an element's visibility
      // WITHOUT adding/removing nodes — a filter UI toggling `style`
      // (display/visibility), `class`, `hidden`, `open` (<details>) or
      // `aria-hidden` changes the searchable corpus but fires no childList/
      // characterData mutation, so the count stayed stale under an open bar.
      // Debounced via scheduleInvalidate; filtered so it isn't storm-prone.
      attributes: true,
      attributeFilter: ["style", "class", "hidden", "open", "aria-hidden"],
    });
    observers.set(target, observer);
  };

  const observeAll = (
    root: Node,
    shadowRoots: ShadowRoot[],
    frameDocs: Document[],
  ) => {
    // Light-DOM root.
    const target =
      root.nodeType === Node.DOCUMENT_NODE
        ? (root as Document).documentElement
        : (root as Element);
    if (target) observeNode(target);
    // Each open shadow root reached by collectRuns.
    shadowRoots.forEach(observeNode);
    // Each same-origin iframe document we descended into.
    frameDocs.forEach((doc) => {
      if (frameDocsObserved.has(doc)) return;
      frameDocsObserved.add(doc);
      const docEl = doc.documentElement;
      if (docEl) observeNode(docEl);
      // IFR-02: input events do NOT cross the iframe boundary, so the
      // top-document capture listener below never hears typing inside a
      // same-origin iframe field — its .value change would leave the corpus
      // cache stale. Attach the same listener to each descended frame doc
      // (cleaned up in teardownObservers via frameDocsObserved).
      try {
        doc.addEventListener("input", onFieldInput, true);
      } catch {
        /* detached / cross-origin — ignore */
      }
    });
    if (!inputListenerAttached && typeof document !== "undefined") {
      // Capture-phase so we still hear the event even if page handlers
      // call stopPropagation in their onChange. This top-document listener
      // only hears input events dispatched in the TOP document; same-origin
      // iframe fields are covered by the per-frame listeners attached above,
      // and cross-origin iframes are unreachable.
      document.addEventListener("input", onFieldInput, true);
      // CMF-38: scrolling reveals previously-skipped `content-visibility: auto`
      // content (now searchable — CMF-37) without firing any DOM mutation, so
      // the corpus would stay stale. A debounced (scheduleInvalidate) scroll
      // listener rebuilds it. Passive + capture so it never blocks scrolling
      // and still fires for scroll containers inside the page. Only live while
      // the bar's cached finder exists (bar open) and only re-searches when a
      // term is active, so the cost is bounded.
      document.addEventListener("scroll", scheduleInvalidate, {
        capture: true,
        passive: true,
      });
      inputListenerAttached = true;
    }
  };

  return {
    find: (term, modifiers, root = document.body) => {
      if (!term || !term.length) return { matches: [], count: 0, text: "" };
      if (!cache || cache.root !== root) {
        const collected = collectRuns(root);
        cache = {
          root,
          text: collected.text,
          runs: collected.runs,
          blockSeparatorOffsets: collected.blockSeparatorOffsets,
        };
        // Tear and re-observe — collectRuns may have discovered new
        // shadow roots / frames that need their own observers.
        teardownObservers();
        observeAll(root, collected.shadowRoots, collected.frameDocs);
      }
      let matches: AdHocMatch[];
      if (modifiers.regex)
        matches = findRegexMatches(cache.text, cache.runs, term, modifiers);
      else if (modifiers.fuzzy)
        matches = findFuzzyMatches(
          cache.text,
          cache.runs,
          term,
          modifiers,
          cache.blockSeparatorOffsets
        );
      else
        matches = findPlainMatches(
          cache.text,
          cache.runs,
          term,
          modifiers,
          cache.blockSeparatorOffsets
        );
      return { matches, count: matches.length, text: cache.text };
    },
    invalidate,
    dispose: teardownObservers,
  };
};

export const __testing = {
  collectRuns,
  findPlainMatches,
  findRegexMatches,
  findFuzzyMatches,
  levenshteinBounded,
  isElementInvisible,
};
