export const addBadgeText = (foundQueries?: number, tabId?: number) => {
  // ADDING TEXT TO BADGE - FOUND NUMBERS

  if (
    !chrome?.action ||
    !chrome?.action?.setBadgeText ||
    !chrome?.action?.setBadgeBackgroundColor
  )
    return;

  // MSG-09: a badge update must be tab-scoped. Today only content scripts send
  // SummaryBadge messages and they always carry sender.tab, but if a badge
  // message ever arrived from a non-tab context, `setBadgeText({tabId:
  // undefined})` would set the DEFAULT (all-tabs) badge — leaking one context's
  // count onto every tab's icon. Bail when we have no tab to scope to rather
  // than falling through to a global badge write.
  if (tabId == null) return;

  chrome.action.setBadgeBackgroundColor({ color: 'rgb(118, 244, 233)' });

  // console.log(foundQueries, 'setBadge');

  chrome.action.setBadgeText({
    text: foundQueries?.toString() || '',
    tabId: tabId,
  });
};
