/**
 * Static heuristic for detecting regex patterns that are likely to
 * cause catastrophic backtracking. JS has no way to interrupt a
 * running RegExp.exec() — the only safe options are (a) reject
 * dangerous patterns before passing them to the engine, or (b) run
 * matching in a Worker we can terminate. Approach (b) is preferable
 * eventually but requires bundling a worker entrypoint; this static
 * check is the cheap defence we ship first.
 *
 * Caught forms (all real-world catastrophic patterns the empirical
 * stress fixture exercises):
 *
 *   - Nested quantifiers on a captured group whose body is also
 *     quantifier-able: `(a+)+`, `(.+)+`, `(.*)+`, `(a*)*`,
 *     `(a+)*`, `(.+){1,5}`, `(a*){2,}`.
 *   - Ambiguous alternation inside a quantifier where the
 *     alternatives can match the same input: `(a|a)*`, `(a|ab)+`,
 *     `(\w|\w)*`.
 *   - Overlapping quantifiers on adjacent atoms that can share input:
 *     `a*a*b`, `\w+\w+`.
 *
 * False positives exist (well-anchored patterns with these shapes can
 * still be safe), but our population of regex queries is small enough
 * that erring on the side of rejection is reasonable — the user
 * receives an explanation and can rewrite.
 *
 * See `regexSafety.test.ts` for the full taxonomy of detected /
 * accepted patterns.
 */

const NESTED_QUANTIFIER_PATTERNS: ReadonlyArray<RegExp> = [
  // (foo+)+, (foo*)+, (foo+)*, (foo*)*, (foo{1,3})+, etc.
  //
  // Look for a parenthesised group whose contents end with a
  // quantifier, immediately followed by another quantifier on the
  // group itself. The group body can contain anything other than
  // an unescaped `)`. Inner quantifier covers ?, *, +.
  //
  // The OUTER quantifier alternation deliberately excludes `?`: a `?`
  // outer quantifier is "0 or 1", which can't blow up exponentially no
  // matter what's inside the group. Real catastrophic shapes use `*`,
  // `+`, or a range `{n,m}` as the outer quantifier.
  /\([^)]*[*+?][^)]*\)[*+{]/,
  // Range-quantifier nested inside a group then quantified again, e.g.
  // (a{1,3})+ — dangerous because the {1,3} introduces overlap. Fixed
  // counts like (a{3})+ don't backtrack ambiguously, so we require a
  // comma in the inner quantifier.
  /\([^)]*\{\d*,\d*\}[^)]*\)[*+{]/,
];

const OVERLAPPING_ADJACENT_QUANTIFIERS: ReadonlyArray<RegExp> = [
  // Plain char repeated quantifier-quantifier: a*a*, b+b+.
  /([A-Za-z])[*+][\s]*\1[*+]/,
];

// `\w+\w+`, `\d+\d+` — two adjacent quantified character classes that can match
// the SAME input overlap and backtrack. But COMPLEMENTARY classes (`\s\S`,
// `\d\D`, `\w\W`) are disjoint — `\s+\S+` is linear-time safe — so we must NOT
// flag those (fixes a false positive). (QRX-05)
const hasOverlappingAdjacentClassQuantifiers = (pattern: string): boolean => {
  const m = /\\([wsdWSD])[*+]\\([wsdWSD])[*+]/.exec(pattern);
  if (!m) return false;
  const [, first, second] = m;
  const complementary =
    first !== second && first.toLowerCase() === second.toLowerCase();
  return !complementary;
};

// True when a quantified group's body itself contains a quantifier — the
// catastrophic nesting `(a+)+`. Unlike the single-level NESTED_QUANTIFIER_PATTERNS
// regexes, this balanced-paren scan handles ARBITRARY nesting depth, so it also
// catches double-wrapped forms like `((a+))+` / `(?:(a+))+` that the regexes miss
// (QRX-05). The outer quantifier must be `*`, `+`, or a `{n,}` range — a `?`
// outer can't blow up, and a fixed `{n}` count doesn't backtrack ambiguously.
const hasNestedQuantifierGroup = (pattern: string): boolean => {
  const isEscaped = (idx: number): boolean => {
    let backslashes = 0;
    for (let k = idx - 1; k >= 0 && pattern[k] === "\\"; k -= 1) backslashes += 1;
    return backslashes % 2 === 1;
  };

  for (let i = 0; i < pattern.length; i += 1) {
    if (pattern[i] !== ")" || isEscaped(i)) continue;
    const rest = pattern.slice(i + 1);
    if (!/^(?:[*+]|\{\d*,\d*\})/.test(rest)) continue; // outer quantifier (not ?)

    let depth = 0;
    let open = -1;
    for (let j = i; j >= 0; j -= 1) {
      if (isEscaped(j)) continue;
      if (pattern[j] === ")") depth += 1;
      else if (pattern[j] === "(") {
        depth -= 1;
        if (depth === 0) {
          open = j;
          break;
        }
      }
    }
    if (open === -1) continue;

    const body = pattern.slice(open + 1, i);
    if (/[*+]/.test(body) || /\{\d*,\d*\}/.test(body)) return true;
  }
  return false;
};

const isAmbiguousAlternationInQuantifier = (pattern: string): boolean => {
  // Cheap structural scan: look for `(...)` followed by `[*+?{`, with
  // an alternation inside whose branches normalise to the same atom.
  // This catches `(a|a)+`, `(\w|\w)*`, `(foo|foo){2,}`.
  // Same `?`-exclusion rationale as NESTED_QUANTIFIER_PATTERNS: `?` as an
  // outer quantifier can't cause catastrophic backtracking, so we restrict
  // the alternation to `*`, `+`, and the opening of a range quantifier.
  const re = /\(([^()]*)\)[*+{]/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(pattern)) !== null) {
    const body = m[1];
    if (!body.includes("|")) continue;
    const branches = body.split("|").map((b) => b.trim());
    const seen = new Set<string>();
    for (const branch of branches) {
      if (seen.has(branch)) return true;
      seen.add(branch);
    }
    // Also flag when one branch is a strict prefix of another and both
    // are followed by a quantifier'd group (classic `(a|ab)+` shape).
    if (branches.length === 2) {
      const [a, b] = branches;
      if (a && b && (b.startsWith(a) || a.startsWith(b))) return true;
    }
  }
  return false;
};

/**
 * Strip non-capturing, lookaround, and named-group prefixes from `(` openings.
 * Without this step the leading `?` / `=` / `!` / `<` / `<name>` inside
 * `(...)` reads to the nested-quantifier detectors as an inner quantifier,
 * triggering false positives on real-world patterns like `(?:/\S*)?` or
 * `(?:\.\d{2})?`.
 *
 * Order matters: lookbehinds (`(?<=`, `(?<!`) come before the named-group
 * rule (`(?<name>`) so the more specific prefix matches first.
 */
const stripGroupPrefixes = (pattern: string): string =>
  pattern
    .replace(/\(\?<=/g, "(")
    .replace(/\(\?<!/g, "(")
    .replace(/\(\?<[^>]*>/g, "(")
    .replace(/\(\?[:=!]/g, "(");

/**
 * Returns true when the given pattern matches a known catastrophic
 * backtracking shape. False does NOT guarantee safety — it means
 * "no known-bad shape detected".
 */
export const isLikelyCatastrophic = (pattern: string): boolean => {
  if (!pattern || typeof pattern !== "string") return false;
  const normalised = stripGroupPrefixes(pattern);
  for (const r of NESTED_QUANTIFIER_PATTERNS) {
    if (r.test(normalised)) return true;
  }
  // Depth-aware nested-quantifier scan — catches `((a+))+` / `(?:(a+))+` that
  // the single-level regexes above miss (QRX-05).
  if (hasNestedQuantifierGroup(normalised)) return true;
  for (const r of OVERLAPPING_ADJACENT_QUANTIFIERS) {
    if (r.test(normalised)) return true;
  }
  // Adjacent quantified classes, excluding disjoint complementary pairs (QRX-05).
  if (hasOverlappingAdjacentClassQuantifiers(normalised)) return true;
  if (isAmbiguousAlternationInQuantifier(normalised)) return true;
  return false;
};
